window.HUR={"b:1": "آپ صلی اللہ علیہ وسلم فرما رہے تھے کہ تمام اعمال کا دارومدار نیت پر ہے اور ہر عمل کا نتیجہ ہر انسان کو اس کی نیت کے مطابق ہی ملے گا ۔ پس جس کی ہجرت ( ترک وطن ) دولت دنیا حاصل کرنے کے لیے ہو یا کسی عورت سے شادی کی غرض ہو ۔ پس اس کی ہجرت ان ہی چیزوں کے لیے ہو گی جن کے حاصل کرنے کی نیت سے اس نے ہجرت کی ہے ۔", "b:3": "آنحضرت صلی اللہ علیہ وسلم پر وحی کا ابتدائی دور اچھے سچے پاکیزہ خوابوں سے شروع ہوا ۔ آپ صلی اللہ علیہ وسلم خواب میں جو کچھ دیکھتے وہ صبح کی روشنی کی طرح صحیح اور سچا ثابت ہوتا ۔ پھر من جانب قدرت آپ صلی اللہ علیہ وسلم تنہائی پسند ہو گئے اور آپ صلی اللہ علیہ وسلم نے غار حرا میں خلوت نشینی اختیار فرمائی اور کئی کئی دن اور رات وہاں مسلسل عبادت اور یاد الٰہی و ذکر و فکر میں مشغول رہتے ۔ جب تک گھر آنے کو دل نہ چاہتا توشہ ہمراہ لیے ہوئے وہاں رہتے ۔ توشہ ختم ہونے پر ہی اہلیہ محترمہ حضرت خدیجہ رضی اللہ عنہا کے پاس تشریف لاتے اور کچھ توشہ ہمراہ لے کر پھر وہاں جا کر خلوت گزیں ہو جاتے ، یہی طریقہ جاری رہا یہاں تک کہ آپ صلی اللہ علیہ وسلم پر حق منکشف ہو گیا اور آپ صلی اللہ علیہ وسلم غار حرا ہی میں قیام پذیر تھے کہ اچانک حضرت جبرائیل علیہ السلام آپ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور کہنے لگے کہ اے محمد ! پڑھو آپ صلی اللہ علیہ وسلم فرماتے ہیں کہ میں نے کہا کہ میں پڑھنا نہیں جانتا ، آپ صلی اللہ علیہ وسلم فرماتے ہیں کہ فرشتے نے مجھے پکڑ کر اتنے زور سے بھینچا کہ میری طاقت جواب دے گئی ، پھر مجھے چھوڑ کر کہا کہ پڑھو ، میں نے پھر وہی جواب دیا کہ میں پڑھا ہوا نہیں ہوں ۔ اس فرشتے نے مجھ کو نہایت ہی زور سے بھینچا کہ مجھ کو سخت تکلیف محسوس ہوئی ، پھر اس نے کہا کہ پڑھ ! میں نے کہا کہ میں پڑھا ہوا نہیں ہوں ۔ فرشتے نے تیسری بار مجھ کو پکڑا اور تیسری مرتبہ پھر مجھ کو بھینچا پھر مجھے چھوڑ دیا اور کہنے لگا کہ پڑھو اپنے رب کے نام کی مدد سے جس نے پیدا کیا اور انسان کو خون کی پھٹکی سے بنایا ، پڑھو اور آپ کا رب بہت ہی مہربانیاں کرنے والا ہے ۔ پس یہی آیتیں آپ صلی اللہ علیہ وسلم حضرت جبرائیل علیہ السلام سے سن کر اس حال میں غار حرا سے واپس ہوئے کہ آپ صلی اللہ علیہ وسلم کا دل اس انوکھے واقعہ سے کانپ رہا تھا ۔ آپ صلی اللہ علیہ وسلم حضرت خدیجہ کے ہاں تشریف لائے اور فرمایا کہ مجھے کمبل اڑھا دو ، مجھے کمبل اڑھا دو ۔ لوگوں نے آپ صلی اللہ علیہ وسلم کو کمبل اڑھا دیا ۔ جب آپ صلی اللہ علیہ وسلم کا ڈر جاتا رہا ۔ تو آپ صلی اللہ علیہ وسلم نے اپنی زوجہ محترمہ حضرت خدیجہ رضی اللہ عنہا کو تفصیل کے ساتھ یہ واقعہ سنایا اور فرمانے لگے کہ مجھ کو اب اپنی جان کا خوف ہو گیا ہے ۔ آپ صلی اللہ علیہ وسلم کی اہلیہ محترمہ حضرت خدیجہ رضی اللہ عنہا نے آپ صلی اللہ علیہ وسلم کی ڈھارس بندھائی اور کہا کہ آپ کا خیال صحیح نہیں ہے ۔ خدا کی قسم آپ کو اللہ کبھی رسوا نہیں کرے گا ، آپ تو اخلاق فاضلہ کے مالک ہیں ، آپ تو کنبہ پرور ہیں ، بے کسوں کا بوجھ اپنے سر پر رکھ لیتے ہیں ، مفلسوں کے لیے آپ کماتے ہیں ، مہمان نوازی میں آپ بےمثال ہیں اور مشکل وقت میں آپ امر حق کا ساتھ دیتے ہیں ۔ ایسے اوصاف حسنہ والا انسان یوں بے وقت ذلت و خواری کی موت نہیں پا سکتا ۔ پھر مزید تسلی کے لیے حضرت خدیجہ رضی اللہ عنہا آپ صلی اللہ علیہ وسلم کو ورقہ بن نوفل کے پاس لے گئیں ، جو ان کے چچا زاد بھائی تھے اور زمانہ جاہلیت میں نصرانی مذہب اختیار کر چکے تھے اور عبرانی زبان کے کاتب تھے ، چنانچہ انجیل کو بھی حسب منشائے خداوندی عبرانی زبان میں لکھا کرتے تھے ۔ ( انجیل سریانی زبان میں نازل ہوئی تھی پھر اس کا ترجمہ عبرانی زبان میں ہوا ۔ ورقہ اسی کو لکھتے تھے ) وہ بہت بوڑھے ہو گئے تھے یہاں تک کہ ان کی بینائی بھی رخصت ہو چکی تھی ۔ حضرت خدیجہ رضی اللہ عنہا نے ان کے سامنے آپ صلی اللہ علیہ وسلم کے حالات بیان کیے اور کہا کہ اے چچا زاد بھائی ! اپنے بھتیجے ( محمد صلی اللہ علیہ وسلم ) کی زبانی ذرا ان کی کیفیت سن لیجیئے وہ بولے کہ بھتیجے آپ نے جو کچھ دیکھا ہے ، اس کی تفصیل سناؤ ۔ چنانچہ آپ صلی اللہ علیہ وسلم نے از اول تا آخر پورا واقعہ سنایا ، جسے سن کر ورقہ بے اختیار ہو کر بول اٹھے کہ یہ تو وہی ناموس ( معزز راز دان فرشتہ ) ہے جسے اللہ نے حضرت موسیٰ علیہ السلام پر وحی دے کر بھیجا تھا ۔ کاش ، میں آپ کے اس عہد نبوت کے شروع ہونے پر جوان عمر ہوتا ۔ کاش میں اس وقت تک زندہ رہتا جب کہ آپ کی قوم آپ کو اس شہر سے نکال دے گی ۔ رسول کریم صلی اللہ علیہ وسلم نے یہ سن کر تعجب سے پوچھا کہ کیا وہ لوگ مجھ کو نکال دیں گے ؟ ( حالانکہ میں تو ان میں صادق و امین و مقبول ہوں ) ورقہ بولا ہاں یہ سب کچھ سچ ہے ۔ مگر جو شخص بھی آپ کی طرح امر حق لے کر آیا لوگ اس کے دشمن ہی ہو گئے ہیں ۔ اگر مجھے آپ کی نبوت کا وہ زمانہ مل جائے تو میں آپ کی پوری پوری مدد کروں گا ۔ مگر ورقہ کچھ دنوں کے بعد انتقال کر گئے ۔ پھر کچھ عرصہ تک وحی کی آمد موقوف رہی ۔", "b:10": "آپ صلی اللہ علیہ وسلم نے فرمایا مسلمان وہ ہے جس کی زبان اور ہاتھ سے مسلمان بچے رہیں اور مہاجر وہ ہے جو ان کاموں کو چھوڑ دے جن سے اللہ نے منع فرمایا ۔ ابوعبداللہ امام بخاری نے فرمایا اور ابومعاویہ نے کہ ہم کو حدیث بیان کی داؤد بن ابی ہند نے ، انھوں نے روایت کی عامر شعبی سے ، انھوں نے کہا کہ میں نے سنا عبداللہ بن عمرو بن عاص سے ، وہ حدیث بیان کرتے ہیں جناب نبی کریم صلی اللہ علیہ وسلم سے ( وہی مذکورہ حدیث ) اور کہا کہ عبدالاعلیٰ نے روایت کیا داؤد سے ، انھوں نے عامر سے ، انھوں نے عبداللہ بن عمرو بن عاص سے ، انھوں نے نبی کریم صلی اللہ علیہ وسلم سے ۔", "b:12": "ایک دن ایک آدمی نے آنحضرت صلی اللہ علیہ وسلم سے پوچھا کہ کون سا اسلام بہتر ہے ؟ فرمایا کہ تم کھانا کھلاؤ ، اور جس کو پہچانو اس کو بھی اور جس کو نہ پہچانو اس کو بھی ، الغرض سب کو سلام کرو ۔", "b:13": "آنحضرت صلی اللہ علیہ وسلم نے فرمایا تم میں سے کوئی شخص ایماندار نہ ہو گا جب تک اپنے بھائی کے لیے وہ نہ چاہے جو اپنے نفس کے لیے چاہتا ہے ۔", "b:38": "آنحضرت صلی اللہ علیہ وسلم نے فرمایا جس نے رمضان کے روزے ایمان اور خالص نیت کے ساتھ رکھے اس کے پچھلے گناہ بخش دیئے گئے ۔", "b:8": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا اسلام کی بنیاد پانچ چیزوں پر قائم کی گئی ہے۔ اول گواہی دینا کہ اللہ کے سوا کوئی معبود نہیں اور بیشک حضرت محمد صلی اللہ علیہ وسلم اللہ کے سچے رسول ہیں اور نماز قائم کرنا اور زکوٰۃ ادا کرنا اور حج کرنا اور رمضان کے روزے رکھنا ۔", "b:1149": "نبی کریم صلی اللہ علیہ وسلم نے حضرت بلال رضی اللہ عنہ سے فجر کے وقت پوچھا کہ اے بلال ! مجھے اپنا سب سے زیادہ امید والا نیک کام بتاؤ جسے تم نے اسلام لانے کے بعد کیا ہے کیونکہ میں نے جنت میں اپنے آگے تمہارے جوتوں کی چاپ سنی ہے ۔ حضرت بلال رضی اللہ عنہ نے عرض کیا میں نے تو اپنے نزدیک اس سے زیادہ امید کا کوئی کام نہیں کیا کہ جب میں نے رات یا دن میں کسی وقت بھی وضو کیا تو میں اس وضو سے نفل نماز پڑھتا رہتا جتنی میری تقدیر لکھی گئی تھی ۔", "b:1276": "ہم نے نبی کریم صلی اللہ علیہ وسلم کے ساتھ صرف اللہ کے لیے ہجرت کی ۔ اب ہمیں اللہ تعالیٰ سے اجر ملنا ہی تھا ۔ ہمارے بعض ساتھی تو انتقال کر گئے اور ( اس دنیا میں ) انہوں نے اپنے کئے کا کوئی پھل نہیں دیکھا ۔ مصعب بن عمیر رضی اللہ عنہ بھی انہیں لوگوں میں سے تھے اور ہمارے بعض ساتھیوں کا میوہ پک گیا اور وہ چن چن کر کھاتا ہے ۔ ( مصعب بن عمیر رضی اللہ عنہ ) احد کی لڑائی میں شہید ہوئے ہم کو ان کے کفن میں ایک چادر کے سوا اور کوئی چیز نہ ملی اور وہ بھی ایسی کہ اگر اس سے سر چھپاتے ہیں تو پاؤں کھل جاتا ہے اور اگر پاؤں ڈھکتے تو سر کھل جاتا ۔ آخر یہ دیکھ کر نبی کریم صلی اللہ علیہ وسلم نے ارشاد فرمایا کہ سر کو چھپا دیں اور پاؤں پر سبز گھاس اذخر نامی ڈال دیں ۔", "b:1395": "نبی کریم صلی اللہ علیہ وسلم نے جب معاذ رضی اللہ عنہ کو یمن ( کا حاکم بنا کر ) بھیجا تو فرمایا کہ تم انہیں اس کلمہ کی گواہی کی دعوت دینا کہ اللہ کے سوا کوئی معبود نہیں اور یہ کہ میں اللہ کا رسول ہوں ۔ اگر وہ لوگ یہ بات مان لیں تو پھر انہیں بتانا کہ اللہ تعالیٰ نے ان پر روزانہ پانچ وقت کی نمازیں فرض کی ہیں ۔ اگر وہ لوگ یہ بات بھی مان لیں تو پھر انہیں بتانا کہ اللہ تعالیٰ نے ان کے مال پر کچھ صدقہ فرض کیا ہے جو ان کے مالدار لوگوں سے لے کر انہیں کے محتاجوں میں لوٹا دیا جائے گا ۔", "b:1739": "دسویں تاریخ کو رسول کریم صلی اللہ علیہ وسلم نے منیٰ میں خطبہ دیا ، خطبہ میں آپ صلی اللہ علیہ وسلم نے پوچھا لوگو ! آج کون سا دن ہے ؟ لوگ بولے یہ حرمت کا دن ہے ، آپ صلی اللہ علیہ وسلم نے پھر پوچھا اور یہ شہر کون سا ہے ؟ لوگوں نے کہا یہ حرمت کا شہر ہے ، آپ صلی اللہ عیہ وسلم نے پوچھا یہ مہینہ کون سا ہے ؟ لوگوں نے کہا یہ حرمت کا مہینہ ہے ، پھر آپ صلی اللہ علیہ وسلم نے فرمایا بس تمہارا خون تمہارے مال اور تمہاری عزت ایک دوسرے پر اسی طرح حرام ہے جیسے اس دن کی حرمت ، اس شہر اور اس مہینہ کی حرمت ہے ، اس کلمہ کو آپ صلی اللہ علیہ وسلم نے کئی بار دہرایا اور پھر آسمان کی طرف سر اٹھا کر کہا اے اللہ ! کیا میں نے ( تیرا پیغام ) پہنچا دیا اے اللہ ! کیا میں نے پہنچا دیا ۔ حضرت عبداللہ بن عباس رضی اللہ عنہما نے بتلایا کہ اس ذا ت کی قسم ! جس کے ہاتھ میں میری جان ہے آنحضرت صلی اللہ علیہ وسلم کی یہ وصیت اپنی تمام امت کے لیے ہے ، لہٰذا حاضر ( اور جاننے والے ) غائب ( اور ناواقف لوگوں کو اللہ کا پیغام ) پہنچا دیں ۔ آپ صلی اللہ علیہ وسلم نے پھر فرمایا دیکھو میرے بعد ایک دوسرے کی گردن مار کر کافر نہ بن جانا ۔", "b:1773": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ایک عمرہ کے بعد دوسرا عمرہ دونوں کے درمیان کے گناہوں کا کفارہ ہے اور حج مبرور کی جزا جنت کے سوا اور کچھ نہیں ہے ۔", "b:1899": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جب رمضان کا مہینہ آتا ہے تو آسمان کے تمام دروازے کھول دیئے جاتے ہیں ، جہنم کے دروازے بند کر دیئے جاتے ہیں اور شیاطین کو زنجیروں سے جکڑ دیا جاتا ہے ۔", "b:1901": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ جو کوئی شب قدر میں ایمان کے ساتھ اور حصول ثواب کی نیت سے عبادت میں کھڑا ہو اس کے تمام اگلے گناہ بخش دیئے جائیں گے اور جس نے رمضان کے روزے ایمان کے ساتھ اور ثواب کی نیت سے رکھے اس کے اگلے تمام گناہ معاف کر دیئے جائیں گے ۔", "b:1904": "رسول کریم صلی اللہ علیہ وسلم نے فرمایا ، اللہ پاک فرماتا ہے کہ انسان کا ہر نیک عمل خود اسی کے لیے ہے مگر روزہ کہ وہ خاص میرے لیے ہے اور میں ہی اس کا بدلہ دوں گا اور روزہ گناہوں کی ایک ڈھال ہے ، اگر کوئی روزے سے ہو تو اسے فحش گوئی نہ کرنی چاہئے اور نہ شور مچائے ، اگر کوئی شخص اس کو گالی دے یا لڑنا چاہئے تو اس کا جواب صرف یہ ہو کہ میں ایک روزہ دار آدمی ہوں ، اس ذات کی قسم جس کے ہاتھ میں محمد ( صلی اللہ علیہ وسلم ) کی جان ہے ! روزہ دار کے منہ کی بو اللہ تعالیٰ کے نزدیک مشک کی خوشبو سے بھی زیادہ بہتر ہے ، روزہ دار کو دو خوشیاں حاصل ہوں گی ( ایک تو جب ) وہ افطا رکرتا ہے تو خوش ہوتا ہے اور ( دوسرے ) جب وہ اپنے رب سے ملاقات کرے گا تو اپنے روزے کا ثواب پاکر خوش ہو گا ۔", "b:1923": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، سحری کھاؤ کہ سحری میں برکت ہوتی ہے ۔", "b:1957": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، میری امت کے لوگوں میں اس وقت تک خیر باقی رہے گی ، جب تک وہ افطار میں جلدی کرتے رہیں گے ۔", "b:2017": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، شب قدر کورمضان کے آخری عشرہ کی طاق راتوں میں ڈھونڈو ۔", "b:2048": "جب ہم مدینہ آئے تو رسول اللہ صلی اللہ علیہ وسلم نے میرے اور سعد بن ربیع انصاری کے درمیان بھائی چارہ کرا دیا ۔ سعد بن ربیع رضی اللہ عنہ نے کہا کہ میں انصار کے سب سے زیادہ مالدار لوگوں میں سے ہوں ۔ اس لیے اپنا آدھا مال میں آپ کو دیتا ہوں اور آپ خود دیکھ لیں کہ میری دو بیویوں میں سے آپ کو کون زیادہ پسند ہے ۔ میں آپ کے لیے انہیں اپنے سے الگ کر دوں گا ( یعنی طلاق دے دوں گا ) جب ان کی عدت پوری ہو جائے تو آپ ان سے نکاح کر لیں ۔ بیان کیا کہ اس پر عبدالرحمٰن رضی اللہ عنہ نے فرمایا ، مجھے ان کی ضرورت نہیں ۔ کیا یہاں کوئی بازار ہے جہاں کاروبار ہوتا ہو ؟ سعد رضی اللہ عنہ نے ” سوق قینقاع “ کا نام لیا ۔ بیان کیا کہ جب صبح ہوئی تو عبدالرحمٰن رضی اللہ عنہ پنیر اور گھی لائے ۔ راوی نے بیان کیا کہ پھر وہ تجارت کے لیے بازار آنے جانے لگے ۔ کچھ دنوں کے بعد ایک دن وہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو زرد رنگ کا نشان ( کپڑے یا جسم پر ) تھا ۔ رسول اللہ نے دریافت فرمایا کیا تم نے شادی کر لی ہے ؟ انہوں نے کہا کہ ہاں ، آپ صلی اللہ علیہ وسلم نے دریافت فرمایا کہ کس سے ؟ بولے کہ ایک انصاری خاتون سے ۔ دریافت فرمایا اور مہر کتنا دیا ہے ؟ عرض کیا کہ ایک گٹھلی برابر سونا دیا ہے یا ( یہ کہا کہ ) سونے کی ایک گٹھلی دی ہے ۔ پھر نبی کریم صلی اللہ علیہ وسلم نے فرمایا ، اچھا تو ولیمہ کر خواہ ایک بکری ہی کا ہو ۔", "b:2285": "رسول کریم صلی اللہ علیہ وسلم نے ( یہودیوں کو ) خیبر کی زمین دے دی تھی کہ اس میں محنت کے ساتھ کاشت کریں اور پیداوار کا آدھا حصہ خود لے لیا کریں ۔ ابن عمر رضی اللہ عنہما نے نافع سے یہ بیان کیا کہ زمین کچھ کرایہ پر دی جاتی تھی ۔ نافع نے اس کرایہ کی تعیین بھی کر دی تھی لیکن وہ مجھے یا دنہیں رہا ۔ اور رافع بن خدیج رضی اللہ عنہ نے بیان کیا کہ نبی کریم صلی اللہ علیہ وسلم نے زمینوں کو کرایہ پر دینے سے منع فرمایا تھا اور عبیداللہ نے نافع سے بیان کیا ، اور ان سے ابن عمر رضی اللہ عنہما نے کہ ( خیبر کے یہودیوں کے ساتھ وہاں کی زمین کا معاملہ برابر چلتا رہا ) یہاں تک کہ حضرت عمر رضی اللہ عنہ نے انہیں جلاوطن کر دیا ۔", "b:2731": "رسول اللہ صلی اللہ علیہ وسلم صلح حدیبیہ کے موقع پر ( مکہ ) جا رہے تھے ‘ ابھی آپ صلی اللہ علیہ وسلم راستے ہی میں تھے ‘ فرمایا خالد بن ولید قریش کے ( دو سو ) سواروں کے ساتھ ہماری نقل و حرکت کا اندازہ لگانے کے لئے مقام غمیم میں مقیم ہے ( یہ قریش کا مقدمۃ الجیش ہے ) اس لئے تم لوگ داہنی طرف سے جاؤ ‘ پس خدا کی قسم خالد کو ان کے متعلق کچھ بھی علم نہ ہو سکا اور جب انہوں نے اس لشکر کا غبار اٹھتا ہوا دیکھا تو قریش کو جلدی جلدی خبر دینے گئے ۔ ادھر نبی کریم صلی اللہ علیہ وسلم چلتے رہے یہاں تک کہ آپ اس گھاٹی پر پہنچے جس سے مکہ میں اترتے ہیں تو آپ صلی اللہ علیہ وسلم کی سواری بیٹھ گئی ۔ صحابہ اونٹنی کو اٹھانے کیلئے حل حل کہنے لگے لیکن وہ اپنی جگہ سے نہ اٹھی ۔ صحابہ رضی اللہ عنہم نے کہا کہ قصواء اڑ گئی آپ صلی اللہ علیہ وسلم نے فرمایا قصواء اڑی نہیں اور نہ یہ اس کی عادت ہے ‘ اسے تو اس ذات نے روک لیا جس نے ہاتھیوں ( کے لشکر ) کو ( مکہ ) میں داخل ہونے سے روک لیا تھا ۔ پھر آپ نے فرمایا کہ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے قریش جو بھی ایسا مطالبہ رکھیں گے جس میں اللہ کی محرمات کی بڑائی ہو تو میں اس کا مطالبہ منظور کر لوں گا ۔ آخر آپ صلی اللہ علیہ وسلم نے اونٹنی کو ڈانٹا تو وہ اٹھ گئی ۔ راوی نے بیان کیا کہ پھر نبی کریم صلی اللہ علیہ وسلم صحابہ سے آگے نکل گئے اور حدیبیہ کے آخری کنارے ثمد ( ایک چشمہ یا گڑھا ) پر جہاں پانی کم تھا ، آپ نے پڑاو کیا ۔ لوگ تھوڑا تھوڑا پانی استعمال کرنے لگے ، انہوں نے پانی کو ٹھہرنے ہی نہیں دیا ، سب کھینچ ڈالا ۔ اب رسول کریم صلی اللہ علیہ وسلم سے پیاس کی شکایت کی گئی تو آپ نے اپنے ترکش میں سے ایک تیر نکال کر دیا کہ اس گڑھے میں ڈال دیں بخدا تیر گاڑتے ہی پانی انہیں سیراب کرنے کے لئے ابلنے لگا اور وہ لوگ پوری طرح سیراب ہو گئے ۔ لوگ اسی حال میں تھے کہ بدیل بن ورقاء خزاعی رضی اللہ عنہ اپنی قوم خزاعہ کے کئی آدمیوں کو لے کر حاضر ہوا ۔ یہ لوگ تہامہ کے رہنے والے تھے اور رسول اللہ صلی اللہ علیہ وسلم کے محرم راز بڑے خیرخواہ تھے ۔ انہوں نے خبر دی کہ میں کعب بن لوئی اور عامر بن لوئی کو پیچھے چھوڑ کر آ رہا ہوں ۔ جنہوں نے حدیبیہ کے پانی کے ذخیروں پر اپنا پڑاؤ ڈال دیا ہے ‘ ان کے ساتھ بکثرت دودھ دینے والی اونٹنیاں اپنے نئے نئے بچوں کے ساتھ ہیں ۔ وہ آپ سے لڑیں گے اور آپ کے بیت اللہ پہنچنے میں رکاوٹ بنیں گے ۔ لیکن آپ نے فرمایا ہم کسی سے لڑنے نہیں آئے ہیں صرف عمرہ کے ارادے سے آئے ہیں اور واقعہ تو یہ ہے ( مسلسل لڑائیوں نے قریش کو بھی کمزور کر دیا ہے اور انہیں بڑا نقصان اٹھانا پڑا ہے ‘ اب اگر وہ چاہیں تو میں ایک مدت ان سے صلح کا معاہدہ کر لوں گا ‘ اس عرصہ میں وہ میرے اور عوام ( کفار مشرکین عرب ) کے درمیان نہ پڑیں پھر اگر میں کامیاب ہو جاؤں اور ( اس کے بعد ) وہ چاہیں تو اس دین ( اسلام ) میں وہ بھی داخل ہو سکتے ہیں ( جس میں اور تمام لوگ داخل ہو چکے ہوں گے ) لیکن اگر مجھے کامیابی نہیں ہوئی تو انہیں بھی آرام مل جائے گا اور اگر انہیں میری پیش کش سے انکار ہے تو اس ذات کی قسم جس کے ہاتھ میں میری جان ہے جب تک میرا سر تن سے جدا نہیں ہو جاتا ‘ میں اس دین کے لئے برابر لڑتا رہوں گا یا پھر اللہ تعالیٰ اسے نافذ ہی فرما دے گا ۔ بدیل رضی اللہ عنہ نے کہا کہ قریش تک آپ کی گفتگو میں پہچاؤں گا چنانچہ وہ واپس ہوئے اور قریش کے یہاں پہنچے اور کہا کہ ہم تمہارے پاس اس شخص ( نبی کریم صلی اللہ علیہ وسلم ) کے یہاں سے آ رہے ہیں اور ہم نے اسے ایک بات کہتے سنا ہے ‘ اگر تم چاہو تو تمہارے سامنے اسے بیان کر سکتے ہیں ۔ قریش کے بے وقوفوں نے کہا کہ ہمیں اس کی ضرورت نہیں کہ تم اس شخص کی کوئی بات ہمیں سناؤ ۔ جو لوگ صائب الرائے تھے ‘ انہوں نے کہا کہ ٹھیک ہے جو کچھ تم نے سنا ہے ہم سے بیان کر دو ۔ انہوں نے کہا کہ میں نے اسے ( آنحضرت صلی اللہ علیہ وسلم ) کو یہ کہتے سنا ہے اور پھر جو کچھ انہوں نے آنحضور صلی اللہ علیہ وسلم سے سنا تھا ‘ سب بیان کر دیا ۔ اس پر عروہ بن مسعود رضی اللہ عنہ ّ ( جو اس وقت تک کفار کے ساتھ تھے ) کھڑے ہوئے اور کہا اے قوم کے لوگو ! کیا تم مجھ پر باپ کی طرح شفقت نہیں رکھتے ۔ سب نے کہا کیوں نہیں ‘ ضرور رکھتے ہیں ۔ عروہ نے پھر کہا کیا میں بیٹے کی طرح تمہارا خیرخواہ نہیں ہوں ‘ انہوں نے کہا کیوں نہیں ۔ عروہ نے پھر کہا تم لوگ مجھ پر کسی قسم کی تہمت لگا سکتے ہو ؟ انہوں نے کہا کہ نہیں ۔ انہوں نے پوچھا کیا تمہیں معلوم نہیں ہے کہ میں نے عکاظ والوں کو تمہاری مدد کے لئے کہا تھا اور جب انہوں نے انکار کیا تو میں نے اپنے گھرانے ‘ اولاد اور ان تمام لوگوں کو تمہارے پاس لا کر کھڑا کر دیا تھا جنہوں نے میرا کہنا مانا تھا ؟ قریش نے کہا کیوں نہیں ( آپ کی باتیں درست ہیں ) اس کے بعد انہوں نے کہا دیکھو اب اس شخص ( نبی کریم صلی اللہ علیہ وسلم ) نے تمہارے سامنے ایک اچھی تجویز رکھی ہے ‘ اسے تم قبول کر لو اور مجھے اس کے پاس ( گفتگو ) کے لئے جانے دو ‘ سب نے کہا آپ ضرور جایئے ۔ چنانچہ عروہ بن مسعود رضی اللہ عنہ آنحضرت صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آپ صلی اللہ علیہ وسلم سے گفتگو شروع کی ۔ آپ صلی اللہ علیہ وسلم نے ان سے بھی وہی باتیں کہیں جو آپ صلی اللہ علیہ وسلم بدیل سے کہہ چکے تھے ‘ عروہ رضی اللہ عنہ نے اس وقت کہا ۔ اے محمد صلی اللہ علیہ وسلم ! بتائیے اگر آپ صلی اللہ علیہ وسلم نے اپنی قوم کو تباہ کر دیا تو کیا اپنے سے پہلے کسی بھی عرب کے متعلق سنا ہے کہ اس نے اپنے خاندان کا نام و نشان مٹا دیا ہو لیکن اگر دوسری بات واقع ہوئی ( یعنی ہم آپ صلی اللہ علیہ وسلم پر غالب ہوئے ) تو میں خدا کی قسم تمہارے ساتھیوں کا منہ دیکھتا ہوں یہ مختلف جنسوں لوگ یہی کریں گے ۔ اس وقت یہ سب لوگ بھاگ جائیں گے اور آپ کو تنہا چھوڑ دیں گے ۔ اس پر ابوبکر رضی اللہ عنہ بولے امص ببظر اللات ( ابے جا ! لات بت کی شرمگاہ چوس لے ) کیا ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس سے بھاگ جائیں گے اور آپ صلی اللہ علیہ وسلم کو تنہا چھوڑ دیں گے ۔ عروہ نے پوچھا کون صاحب ہیں ؟ لوگوں نے بتایا کہ ابوبکر رضی اللہ عنہ ہیں ۔ عروہ نے کہا اس ذات کی قسم جس کے ہاتھ میں میری جان ہے اگر تمہارا مجھ پر ایک احسان نہ ہوتا جس کا اب تک میں بدلہ نہیں دے سکا ہوں تو تمہیں ضرور جواب دیتا ۔ بیان کیا کہ وہ نبی کریم صلی اللہ علیہ وسلم سے پھر گفتگو کرنے لگے اور گفتگو کرتے ہوئے آپ صلی اللہ علیہ وسلم کی داڑھی مبارک پکڑ لیا کرتے تھے ۔ مغیرہ بن شعبہ رضی اللہ عنہ نبی کریم صلی اللہ علیہ وسلم کے پاس کھڑے تھے ‘ تلوار لٹکائے ہوئے اور سر پر خود پہنے ۔ عروہ جب بھی نبی کریم صلی اللہ علیہ وسلم کی داڑھی مبارک کی طرف اپنا ہاتھ لے جاتے تو مغیرہ رضی اللہ عنہ تلوار کی کو تہی کو ان کے ہاتھ پر مارتے اور ان سے کہتے کہ رسول اللہ صلی اللہ علیہ وسلم کی داڑھی سے اپنا ہاتھ الگ رکھ ۔ عروہ رضی اللہ عنہ نے اپنا سر اٹھایا اور پوچھا یہ کون صاحب ہیں ؟ لوگوں نے بتایا کہ مغیرہ بن شعبہ ۔ عروہ نے انہیں مخاطب کر کے کہا اے دغاباز ! کیا میں نے تیری دغابازی کی سزا سے تجھ کو نہیں بچایا ؟ اصل میں مغیرہ رضی اللہ عنہ ( اسلام لانے سے پہلے ) جاہلیت میں ایک قوم کے ساتھ رہے تھے پھر ان سب کو قتل کر کے ان کا مال لے لیا تھا ۔ اس کے بعد ( مدینہ ) آئے اور اسلام کے حلقہ بگوش ہو گئے ( تو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں ان کا مال بھی رکھ دیا کہ جو چاہیں اس کے متعلق حکم فرمائیں ) لیکن آنحضور صلی اللہ علیہ وسلم نے فرمایا تھا کہ تیرا اسلام تو میں قبول کرتا ہوں ، رہا یہ مال تو میرا اس سے کوئی واسطہ نہیں ۔ کیونکہ وہ دغابازی سے ہاتھ آیا ہے جسے میں لے نہیں سکتا ‘ پھر عروہ رضی اللہ عنہ گھور گھور کر رسول اللہ صلی اللہ علیہ وسلم کے اصحاب کی نقل و حرکت دیکھتے رہے ۔ پھر راوی نے بیان کیا کہ قسم اللہ کی اگر کبھی رسول اللہ صلی اللہ علیہ وسلم نے بلغم بھی تھوکا تو آپ صلی اللہ علیہ وسلم کے اصحاب نے اپنے ہاتھوں پر اسے لے لیا اور اسے اپنے چہرہ اور بدن پر مل لیا ۔ کسی کام کا اگر آپ صلی اللہ علیہ وسلم نے حکم دیا تو اس کی بجاآوری میں ایک دوسرے پر لوگ سبقت لے جانے کی کوشش کرتے ۔ آپ صلی اللہ علیہ وسلم وضو کرنے لگے تو ایسا معلوم ہوا کہ آپ صلی اللہ علیہ وسلم کے وضو کے پانی پر لڑائی ہو جائے گی ( یعنی ہر شخص اس پانی کو لینے کی کوشش کرتا تھا ) جب آپ گفتگو کرنے لگے تو سب پر خاموشی چھا جاتی ۔ آپ کی تعظیم کا یہ حال تھا کہ آپ صلی اللہ علیہ وسلم کے ساتھی نظر بھر کر آپ صلی اللہ علیہ وسلم کو دیکھ بھی نہیں سکتے تھے ۔ خیر عروہ جب اپنے ساتھیوں سے جا کر ملے تو ان سے کہا اے لوگو ! قسم اللہ کی میں بادشاہوں کے دربار میں بھی وفد لے کر گیا ہوں ‘ قیصر و کسریٰ اور نجاشی سب کے دربار میں لیکن اللہ کی قسم میں نے کبھی نہیں دیکھا کہ کسی بادشاہ کے ساتھی اس کی اس درجہ تعظیم کرتے ہوں جتنی محمد صلی اللہ علیہ وسلم کے اصحاب آپ کی تعظیم کرتے ہیں ۔ قسم اللہ کی اگر محمد صلی اللہ علیہ وسلم نے بلغم بھی تھوک دیا تو ان کے اصحاب نے اسے اپنے ہاتھوں میں لے لیا اور اسے اپنے چہرہ اور بدن پر مل لیا ۔ آپ صلی اللہ علیہ وسلم نے انہیں اگر کوئی حکم دیا تو ہر شخص نے اسے بجا لانے میں ایک دوسرے پر سبقت کی کوشش کی ۔ آپ صلی اللہ علیہ وسلم نے اگر وضو کیا تو ایسا معلوم ہوتا کہ آپ صلی اللہ علیہ وسلم کے وضو پر لڑائی ہو جائے گی ۔ آپ صلی اللہ علیہ وسلم نے جب گفتگو شروع کی تو ہر طرف خاموشی چھا گئی ۔ ان کے دلوں میں آپ صلی اللہ علیہ وسلم کی تعظیم کا یہ عالم تھا کہ آپ صلی اللہ علیہ وسلم کو نظر بھر کر بھی نہیں دیکھ سکتے ۔ انہوں نے تمہارے سامنے ایک بھلی صورت رکھی ہے ‘ تمہیں چاہئے کہ اسے قبول کر لو ۔ اس پر بنو کنانہ کا ایک شخص بولا کہ اچھا مجھے بھی ان کے یہاں جانے دو ‘ لوگوں نے کہا تم بھی جا سکتے ہو ۔ جب یہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے اصحاب رضوان اللہ علیہم اجمعین کے قریب پہنچے تو حضور اکرم صلی اللہ علیہ وسلم نے فرمایا کہ یہ فلاں شخص ہے ‘ ایک ایسی قوم کا فرد جو بیت اللہ کی قربانی کے جانوروں کی تعظیم کرتے ہیں ۔ اس لئے قربانی کے جانور اس کے سامنے کر دو ۔ صحابہ رضی اللہ عنہم نے قربانی کے جانور اس کے سامنے کر دیئے اور لبیک کہتے ہوئے اس کا استقبال کیا جب اس نے یہ منظر دیکھا تو کہنے لگا کہ سبحان اللہ قطعاً مناسب نہیں ہے کہ ایسے لوگوں کو کعبہ سے روکا جائے ۔ اس کے بعد قریش میں سے ایک دوسرا شخص مکرز بن حفص نامی کھڑا ہوا اور کہنے لگا کہ مجھے بھی ان کے یہاں جانے دو ۔ سب نے کہا کہ تم بھی جا سکتے ہو جب وہ آنحضرت صلی اللہ علیہ وسلم اور صحابہ رضی اللہ عنہم سے قریب ہوا تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ یہ مکرز ہے ایک بدترین شخص ہے ۔ پھر وہ نبی کریم صلی اللہ علیہ وسلم سے گفتگو کرنے لگا ۔ ابھی وہ گفتگو کر ہی رہا تھا کہ سہیل بن عمر و آ گیا ۔ معمر نے ( سابقہ سند کے ساتھ ) بیان کیا کہ مجھے ایوب نے خبر دی اور انہیں عکرمہ نے کہ جب سہیل بن عمرو آیا تو نبی کریم صلی اللہ علیہ وسلم نے ( نیک فالی کے طور پر ) فرمایا تمہارا معاملہ آسان ( سہل ) ہو گیا ۔ معمر نے بیان کیا کہ زہری نے اپنی حدیث میں اس طرح بیان کیا تھا کہ جب سہیل بن عمرو آیا تو کہنے لگا کہ ہمارے اور اپنے درمیان ( صلح ) کی ایک تحریر لکھ لو ۔ چنانچہ نبی کریم صلی اللہ علیہ وسلم نے کاتب کو بلوایا اور فرمایا کہ لکھو بسم اللہ الرحمن الرحیم سہیل کہنے لگا رحمن کو اللہ کی قسم میں نہیں جانتا کہ وہ کیا چیز ہے ۔ البتہ تم یوں لکھ سکتے ہو باسمک اللھم جیسے پہلے لکھا کرتے تھے مسلمانوں نے کہا کہ قسم اللہ کی ہمیں بسم اللہ الرحمان الرحیم کے سوا اور کوئی دوسرا جملہ نہ لکھنا چاہئے ۔ لیکن آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ باسمک اللھم ہی لکھنے دو ۔ پھر آپ صلی اللہ علیہ وسلم نے لکھوایا یہ محمد رسول اللہ کی طرف سے صلح نامہ کی دستاویز ہے ( صلی اللہ علیہ وسلم ) سہیل نے کہا اگر ہمیں یہ معلوم ہوتا کہ آپ رسول اللہ ہیں تو نہ ہم آپ صلی اللہ علیہ وسلم کو کعبہ سے روکتے اور نہ آپ سے جنگ کرتے ۔ آپ صلی اللہ علیہ وسلم تو صرف اتنا لکھئے کہ ” محمد بن عبداللہ “ اس پر رسول کریم صلی اللہ علیہ وسلم نے فرمایا اللہ گواہ ہے کہ میں اس کا سچا رسول ہوں خواہ تم میری تکذیب ہی کرتے رہو ‘ لکھو جی ” محمد بن عبداللہ “ زہری نے بیان کیا کہ یہ سب کچھ ( نرمی اور رعایت ) صرف آپ صلی اللہ علیہ وسلم کے اس ارشاد کا نتیجہ تھا ( جو پہلے بدیل رضی اللہ عنہ سے کہہ چکے تھے ) کہ قریش مجھ سے جو بھی ایسا مطالبہ کریں گے جس سے اللہ تعالیٰ کی حرمتوں کی تعظیم مقصود ہو گی تو میں ان کے مطالبے کو ضرور مان لوں گا ‘ اس لئے نبی کریم صلی اللہ علیہ وسلم نے سہیل سے فرمایا لیکن صلح کے لئے پہلی شرط یہ ہو گی کہ تم لوگ ہمیں بیت اللہ کے طواف کرنے کے لئے جانے دو گے ۔ سہیل نے کہا قسم اللہ کی ہم ( اس سال ) ایسا نہیں ہونے دیں گے ورنہ عرب کہیں گے ہم مغلوب ہو گئے تھے ( اس لئے ہم نے اجازت دے دی ) آئندہ سال کے لئے اجازت ہے ۔ چنانچہ یہ بھی لکھ لیا ۔ پھر سہیل نے لکھا کہ یہ شرط بھی ( لکھ لیجئے ) کہ ہماری طرف کا جو شخص بھی آپ صلی اللہ علیہ وسلم کے یہاں جائے گا خواہ وہ آپ صلی اللہ علیہ وسلم کے دین ہی پر کیوں نہ ہو آپ صلی اللہ علیہ وسلم اسے ہمیں واپس کر دیں گے ۔ مسلمانوں نے ( یہ شرط سن کر کہا ) سبحان اللہ ! ( ایک شخص کو ) مشرکوں کے حوالے کس طرح کیا جا سکتا ہے جو مسلمان ہو کر آیا ہو ۔ ابھی یہی باتیں ہو رہی تھیں کہ ابو جندل بن سہیل بن عمرو رضی اللہ عنہ اپنی بیڑیوں کو گھسیٹتے ہوئے آ پہنچے ‘ وہ مکہ کے نشیبی علاقے کی طرف سے بھاگے تھے اور اب خود کو مسلمانوں کے سامنے ڈال دیا تھا ۔ سہیل نے کہا اے محمد صلی اللہ علیہ وسلم ! یہ پہلا شخص ہے جس کے لئے ( صلح نامہ کے مطابق ) میں مطالبہ کرتا ہوں کہ آپ صلی اللہ علیہ وسلم ہمیں اسے واپس کر دیں ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ ابھی تو ہم نے ( صلح نامہ کی اس دفعہ کو ) صلح نامہ میں لکھا بھی نہیں ہے ( اس لئے جب صلح نامہ طے پا جائے گا اس کے بعد اس کا نفاذ ہونا چاہئے ) سہیل کہنے لگا کہ اللہ کی قسم پھر میں کسی بنیاد پر بھی آپ صلی اللہ علیہ وسلم سے صلح نہیں کروں گا ۔ نبی کریم صلی اللہ علیہ وسلم نے فرمایا اچھا مجھ پر اس ایک کو دے کر احسان کر دو ۔ اس نے کہا کہ میں اس سلسلے میں احسان بھی نہیں کر سکتا ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ نہیں ہمیں احسان کر دینا چاہئے لیکن اس نے یہی جواب دیا کہ میں ایسا کبھی نہیں کر سکتا ۔ البتہ مکرز نے کہا کہ چلئے ہم اس کا آپ صلی اللہ علیہ وسلم پر احسان کرتے ہیں مگر ( اس کی بات نہیں چلی ) ابو جندل رضی اللہ عنہ نے کہا مسلمانوں ! میں مسلمان ہو کر آیا ہوں ۔ کیا مجھے مشرکوں کے ہاتھ میں دے دیا جائے گا ؟ کیا میرے ساتھ جو اذیتیں پہنچائی گئیں تھیں ۔ راوی نے بیان کیا کہ عمر بن خطاب رضی اللہ عنہ نے کہا آخر میں نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کیا کیا یہ واقعہ اور حقیقت نہیں کہ آپ صلی اللہ علیہ وسلم اللہ کے نبی ہیں ؟ آپ صلی اللہ علیہ وسلم نے فرمایا کیوں نہیں ! میں نے عرض کیا کیا ہم حق پر نہیں ہیں اور کیا ہمارے دشمن باطل پر نہیں ہیں ؟ آپ صلی اللہ علیہ وسلم نے فرمایا کیوں نہیں ! میں نے کہا پھر اپنے دین کے معاملے میں کیوں دبیں ۔ آنحضور صلی اللہ علیہ وسلم نے فرمایا میں اللہ کا رسول ہوں ‘ اس کی حکم عدولی نہیں کر سکتا اور وہی میرا مددگار ہے ۔ میں نے کہا کیا آپ صلی اللہ علیہ وسلم ہم سے یہ نہیں فرماتے تھے کہ ہم بیت اللہ جائیں گے اور اس کا طواف کریں گے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ ٹھیک ہے لیکن کیا میں نے تم سے یہ کہا تھا کہ اسی سا ل ہم بیت اللہ پہنچ جائیں گے ۔ عمر رضی اللہ عنہ نے بیان کیا کہ میں نے کہا نہیں ( آپ صلی اللہ علیہ وسلم نے اس قید کے ساتھ نہیں فرمایا تھا ) آپ صلی اللہ علیہ وسلم نے فرمایا کہ پھر اس میں کوئی شبہ نہیں کہ تم بیت اللہ تک ضرور پہنچو گے اور ایک دن اس کا طواف کرو گے ۔ انہوں نے بیان کیا کہ پھر ابوبکر رضی اللہ عنہ کے یہاں گیا اور ان سے بھی یہی پوچھا کہ ابوبکر ! کیا یہ حقیقت نہیں کہ آنحضرت صلی اللہ علیہ وسلم اللہ کے نبی ہیں ؟ انہوں نے بھی کہا کہ کیوں نہیں ۔ میں نے پوچھا کیا ہم حق پر نہیں ہیں ؟ اور کیا ہمارے دشمن باطل پر نہیں ہیں ؟ انہوں نے کہا کیوں نہیں ! میں نے کہا کہ پھر اپنے دین کو کیوں ذلیل کریں ۔ ابوبکر رضی اللہ عنہ نے کہا جناب ! بلا شک و شبہ وہ اللہ کے رسول ہیں ‘ اور اپنے رب کی حکم عدولی نہیں کر سکتے اور رب ہی ان کا مددگار ہے پس ان کی رسی مضبوطی سے پکڑ لو ‘ خدا گواہ ہے کہ وہ حق پر ہیں ۔ میں نے کہا کیا آنحضور ہم سے یہ نہیں کہتے تھے کہ عنقریب ہم بیت اللہ پہونچیں گے اور اس کا طواف کریں گے انہوں نے فرمایا کہ یہ بھی صحیح ہے لیکن کیا آنحضرت صلی اللہ علیہ وسلم نے آپ سے یہ فرمایا تھا کہ اسی سال آپ بیت اللہ پہنچ جائیں گے ۔ میں نے کہا کہ نہیں ۔ پھر ابوبکر رضی اللہ عنہ نے کہا پھر اس میں بھی کوئی شک وشبہ نہیں کہ آپ ایک نہ ایک دن بیت اللہ پہنچیں گے اور اس کا طواف کریں گے ۔ زہری نے بیان کیا کہ عمر رضی اللہ عنہ نے فرمایا بعد میں میں نے اپنی عجلت پسندی کی مکافات کے لئے نیک اعمال کئے ۔ پھر جب صلح نامہ سے آپ فارغ ہو چکے تو صحابہ رضوان اللہ علیہم سے فرمایا کہ اب اٹھو اور ( جن جانوروں کو ساتھ لائے ہو ان کی ) قربانی کر لو اور سر بھی منڈوا لو ۔ انہوں نے بیان کیا کہ اللہ گواہ ہے صحابہ میں سے ایک شخص بھی نہ اٹھا اور تین مرتبہ آپ صلی اللہ علیہ وسلم نے یہ جملہ فرمایا ۔ جب کوئی نہ اٹھا تو نبی کریم صلی اللہ علیہ وسلم ام سلمہ کے خیمہ میں گئے اور ان سے لوگوں کے طرز عمل کا ذکر کیا ۔ حضرت ام سلمہ رضی اللہ عنہا نے کہا اے اللہ کے نبی ! کیا آپ یہ پسند کریں گے کہ باہر تشریف لے جائیں اور کسی سے کچھ نہ کہیں بلکہ اپنا قربانی کا جانور ذبح کر لیں اور اپنے حجام کو بلا لیں جو آپ کے بال مونڈ دے ۔ چنانچہ آنحضرت صلی اللہ علیہ وسلم باہر تشریف لائے ۔ کسی سے کچھ نہیں کہا اور سب کچھ کیا ‘ اپنے جانور کی قربانی کر لی اور اپنے حجام کو بلوایا جس نے آپ صلی اللہ علیہ وسلم کے بال مونڈے ۔ جب صحابہ نے دیکھا تو وہ بھی ایک دوسرے کے بال مونڈنے لگے ‘ ایسا معلوم ہوتا تھا کہ رنج و غم میں ایک دوسرے سے لڑ پڑیں گے ۔ پھر آنحضور صلی اللہ علیہ وسلم کے پاس ( مکہ سے ) چند مومن عورتیں آئیں تو اللہ تعالیٰ نے یہ حکم نازل فرمایا ‘ اے لوگو ! جو ایمان لا چکے ہو جب تمہارے پاس مومن عورتیں ہجرت کر کے آئیں تو ان کا امتحان لے لوبعصم الکوافر تک ۔ اس دن حضرت عمر رضی اللہ عنہ نے اپنی دو بیویوں کو طلاق دی جو اب تک مسلمان نہ ہوئی تھیں ۔ ان میں سے ایک نے تو معاویہ بن ابی سفیان رضی اللہ عنہ سے نکاح کر لیا تھا اور دوسری سے صفوان بن امیہ نے ۔ اس کے بعد رسول اللہ صلی اللہ علیہ وسلم مدینہ واپس تشریف لائے تو قریش کے ایک فرد ابوبصیر رضی اللہ عنہ ( مکہ سے فرار ہو کر ) حاضر ہوئے ۔ وہ مسلمان ہو چکے تھے ۔ قریش نے انہیں واپس لینے کے لئے دو آدمیوں کو بھیجا اور انہوں نے آ کر کہا کہ ہمارے ساتھ آپ کا معاہدہ ہو چکا ہے ۔ چنانچہ آنحضرت صلی اللہ علیہ وسلم نے ابوبصیر رضی اللہ عنہ کو واپس کر دیا ۔ قریش کے دونوں افراد جب انہیں واپس لے کر لوٹے اور ذوالحلیفہ پہنچے تو کھجور کھانے کے لئے اترے جو ان کے ساتھ تھی ۔ ابو بصیر رضی اللہ عنہ نے ان میں سے ایک سے فرمایا قسم اللہ کی تمہاری تلوار بہت اچھی معلوم ہوتی ہے ۔ دوسرے ساتھی نے تلوار نیام سے نکال دی ۔ اس شخص نے کہا ہاں اللہ کی قسم نہایت عمدہ تلوار ہے ‘ میں اس کا بارہا تجربہ کر چکا ہوں ۔ ابو بصیر رضی اللہ عنہ اس پر بولے کہ ذرا مجھے بھی تو دکھاؤ اور اس طرح اپنے قبضہ میں کر لیا پھر اس شخص نے تلوار کے مالک کو ایسی ضرب لگائی کہ وہ وہیں ٹھنڈا ہو گیا ۔ اس کا دوسرا ساتھی بھاگ کر مدینہ آیا اور مسجد میں دوڑتا ہوا ۔ داخل ہوا نبی کریم صلی اللہ علیہ وسلم نے جب اسے دیکھا تو فرمایا یہ شخص کچھ خوف زدہ معلوم ہوتا ہے ۔ جب وہ آنحضرت صلی اللہ علیہ وسلم کے قریب پہنچا تو کہنے لگا اللہ کی قسم میرا ساتھی تو مارا گیا اور میں بھی مارا جاؤں گا ( اگر آپ لوگوں نے ابو بصیر کو نہ روکا ) اتنے میں ابو بصیر بھی آ گئے اور عرض کیا اے اللہ کے نبی ! اللہ کی قسم اللہ تعالیٰ نے آپ کی ذمہ داری پوری کر دی ‘ آپ مجھے ان کے حوالے کر چکے تھے لیکن اللہ تعالیٰ نے مجھے ان سے نجات دلائی ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا ( تیری ماں کی خرابی ) اگر اس کا کوئی ایک بھی مددگار ہوتا تو پھر لڑائی کے شعلے بھڑک اٹھتے ۔ جب انہوں نے آپ صلی اللہ علیہ وسلم کے یہ الفاظ سنے تو سمجھ گئے کہ آپ پھر کفار کے حوالے کر دیں گے اس لئے وہاں سے نکل گئے اور سمندر کے کنارے پر آ گئے ۔ راوی نے بیان کیا کہ اپنے گھر والوں ( مکہ سے ) چھوٹ کر ابوجندل بن سہیل رضی اللہ عنہ بھی ابو بصیر رضی اللہ عنہ سے جا ملے اور اب یہ حال تھا کہ قریش کا جو شخص بھی اسلام لاتا ( بجائے مدینہ آنے کے ) ابو بصیر رضی اللہ عنہ کے یہاں ( ساحل سمندر پر ) چلا جاتا ۔ اس طرح سے ایک جماعت بن گئی اور اللہ گواہ ہے یہ لوگ قریش کے جس قافلے کے متعلق بھی سن لیتے کہ وہ شام جا رہا ہے تو اسے راستے ہی میں روک کر لوٹ لیتے اور قافلہ والوں کو قتل کر دیتے ۔ اب قریش نے نبی کریم صلی اللہ علیہ وسلم کے یہاں اللہ اور رحم کا واسطہ دے کر درخواست بھیجی کہ آپ کسی کو بھیجیں ( ابو بصیر رضی اللہ عنہ اور ان کے دوسرے ساتھیوں کے یہاں کہ وہ قریش کی ایذا سے رک جائیں ) اور اس کے بعد جو شخص بھی آپ کے یہاں جائے گا ( مکہ سے ) اسے امن ہے ۔ چنانچہ آنحضرت صلی اللہ علیہ وسلم نے ان کے یہاں اپنا آدمی بھیجا اور اللہ تعالیٰ نے یہ آیت نازل فرمائی کہ ” اور وہ ذات پروردگار جس نے روک دیا تھا تمہارے ہاتھوں کو ان سے اور ان کے ہاتھوں کو تم سے ( یعنی جنگ نہیں ہو سکی تھی ) وادی مکہ میں ( حدیبیہ میں ) بعد میں اس کے کہ تم کو غالب کر دیا تھا ان پر یہاں تک کہ بات جاہلیت کے دور کی بے جا حمایت تک پہنچ گئی تھی ) ۔ “ ان کی حمیت ( جاہلیت ) یہ تھی کہ انہوں نے ( معاہدے میں بھی ) آپ کے لئے اللہ کے نبی ہونے کا اقرار نہیں کیا اسی طرح انہوں نے بسم اللہ الرحمن الرحیم نہیں لکھنے دیا اور آپ بیت اللہ جانے سے مانع بنے ۔", "b:2778": "جب حضرت عثمان غنی رضی اللہ عنہ محاصرے میں لئے گئے تو ( اپنے گھر کے ) اوپر چڑھ کر آپ نے باغیوں سے فرمایا میں تم کو خدا کی قسم دے کر پوچھتا ہوں اور صرف نبی کریم صلی اللہ علیہ وسلم کے اصحاب سے قسمیہ پوچھتا ہوں کہ کیا آپ لوگوں کو معلوم نہیں ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو شخص بیئر رومہ کو کھودے گا اور اسے مسلمانوں کے لئے وقف کر دے گا تو اسے جنت کی بشارت ہے تو میں نے ہی اس کنویں کو کھودہ تھا ۔ کیا آپ لوگوں کو معلوم نہیں ہے کہ آنحضرت صلی اللہ علیہ وسلم نے جب فرمایا تھا کہ جیش عسرت ( غزوہ تبوک پر جانے والے لشکر ) کو جو شخص ساز و سامان سے لیس کر دے گا تو اسے جنت کی بشارت ہے تو میں نے ہی اسے مسلح کیا تھا ۔ راوی نے بیان کیا کہ آپ کی ان باتوں کی سب نے تصدیق کی تھی ۔ حضرت عمر رضی اللہ عنہ نے اپنے وقف کے متعلق فرمایا تھا کہ اس کا منتظم اگر اس میں سے کھائے تو کوئی حرج نہیں ہے ۔ ظاہر ہے کہ منتظم خود واقف بھی ہو سکتا ہے اور کبھی دوسرے بھی ہو سکتے ہیں اور ہر ایک کے لئے یہ جائز ہے ۔", "b:2834": "نبی کریم صلی اللہ علیہ وسلم ( غزوہ خندق کے شروع ہونے سے کچھ پہلے جب خندق کی کھدائی ہو رہی تھی ) میدان خندق کی طرف تشریف لے گئے ‘ آپ نے دیکھا کہ مہاجرین اور انصار رضوان اللہ علیہم اجمعین سردی کی سختی کے باوجود صبح ہی صبح خندق کھودنے میں مصروف ہیں ‘ ان کے پاس غلام بھی نہیں تھے جو ان کی اس کھدائی میں مدد کرتے ۔ آپ صلی اللہ علیہ وسلم نے ان کی تھکن اور بھوک کو دیکھا تو آپ صلی اللہ علیہ وسلم نے دعا فرمائی ” اے اللہ ! زندگی تو پس آخرت ہی کی زندگی ہے پس انصار اور مہاجرین کی مغفرت فرما ، “ یعنی درحقیقت جو مزہ ہے آخرت کا ہے مزہ ۔۔۔ بخش دے انصار اور پردیسیوں کو اے خدا ۔۔۔ صحابہ نے اس کے جواب میں کہا ” ہم وہ ہیں جنہوں نے محمد صلی اللہ علیہ وسلم کے ہاتھ پر اس وقت تک جہاد کرنے کا عہد کیا ہے جب تک ہماری جان میں جان ہے “ اپنے پیغمبر محمد صلی اللہ علیہ وسلم سے یہ بیعت ہم نے کی جب تلک ہے زندگی لڑتے رہیں گے ہم سدا ۔", "b:2979": "جب رسول اللہ صلی اللہ علیہ وسلم نے مدینہ کی ہجرت کا ارادہ کیا تو میں نے ( والد ماجد حضرت ) ابوبکر رضی اللہ عنہ کے گھر آپ کے لیے سفر کا ناشتہ تیار کیا تھا ۔ انہوں نے بیان کیا کہ جب آپ کے ناشتے اور پانی کو باندھنے کے لیے کوئی چیز نہیں ملی ، تو میں نے ابوبکر رضی اللہ عنہ سے کہا کہ بجز میرے کمربند کے اور کوئی چیز اسے باندھنے کے لیے نہیں ہے ۔ تو انہوں نے فرمایا کہ پھر اسی کے دو ٹکڑے کر لو ۔ ایک سے ناشتہ باند ھ دینا اور دوسرے سے پانی ، چنانچہ اس نے ایسا ہی کیا ، اور اسی وجہ سے میرا نام ’ ذات النطاقین “ ( دو کمربندوں والی ) پڑ گیا ۔", "b:2989": "رسول کریم صلی اللہ علیہ وسلم نے فرمایا انسان کے ہر ایک جوڑ پر صدقہ لازم ہوتا ہے ۔ ہر دن جس میں سورج طلوع ہوتا ہے ۔ پھر اگر وہ انسانوں کے درمیان انصاف کرے تو یہ بھی ایک صدقہ ہے اور کسی کو سواری کے معاملے میں اگر مدد پہنچائے ، اس طرح پر کہ اسے اس پر سوار کرائے یا اس کا سامان اٹھا کر رکھ دے تو یہ بھی ایک صدقہ ہے اور اچھی بات منہ سے نکالنا بھی ایک صدقہ ہے اور ہر قدم جو نماز کے لیے اٹھتا ہے وہ بھی صدقہ ہے اور اگر کوئی راستے سے کسی تکلیف دینے والی چیز کو ہٹا دے تو وہ بھی ایک صدقہ ہے ۔", "b:3039": "رسول کریم صلی اللہ علیہ وسلم نے جنگ احد کے موقع پر ( تیراندازوں کے ) پچاس آدمیوں کا افسر عبداللہ بن جبیر رضی اللہ عنہ کو بنایا تھا ۔ آپ صلی اللہ علیہ وسلم نے انہیں تاکید کر دی تھی کہ اگر تم یہ بھی دیکھ لو کہ پرندے ہم پر ٹوٹ پڑے ہیں ۔ پھر بھی اپنی جگہ سے مت ہٹنا ‘ جب تک میں تم لوگوں کو کہلا نہ بھیجوں ۔ اسی طرح اگر تم یہ دیکھو کہ کفار کو ہم نے شکست دے دی ہے اور انہیں پامال کر دیا ہے پھر بھی یہاں سے نہ ٹلنا ‘ جب میں تمہیں خود بلا نہ بھیجوں ۔ پھر اسلامی لشکر نے کفار کو شکست دے دی ۔ براء بن عازب رضی اللہ عنہ نے بیان کیا ‘ کہ اللہ کی قسم ! میں نے مشرک عورتوں کو دیکھا کہ تیزی کے ساتھ بھاگ رہی تھیں ۔ ان کے پازیب اور پنڈلیاں دکھائی دے رہی تھیں ۔ اور وہ اپنے کپڑوں کو اٹھائے ہوئے تھیں ۔ عبداللہ بن جبیر رضی اللہ عنہ کے ساتھیوں نے کہا ‘ کہ غنیمت لوٹو ‘ اے قوم ! غنیمت تمہارے سامنے ہے ۔ تمہارے ساتھی غالب آ گئے ہیں ۔ اب ڈر کس بات کا ہے ۔ اس پر عبداللہ بن جبیر رضی اللہ عنہ نے ان سے کہا کہ کیا جو ہدایت رسول اللہ صلی اللہ علیہ وسلم نے کی تھی ‘ تم اسے بھول گئے ؟ لیکن وہ لوگ اسی پر اڑے رہے کہ دوسرے اصحاب کے ساتھ غنیمت جمع کرنے میں شریک رہیں گے ۔ جب یہ لوگ ( اکثریت ) اپنی جگہ چھوڑ کر چلے آئے تو ان کے منہ کافروں نے پھیر دیئے ‘ اور ( مسلمانوں کو ) شکست زدہ پا کر بھاگتے ہوئے آئے ‘ یہی وہ گھڑی تھی ( جس کا ذکر سورۃ آل عمران میں ہے کہ ) ” جب رسول کریم صلی اللہ علیہ وسلم تم کو پیچھے کھڑے ہوئے بلا رہے تھے “ ۔ اس سے یہی مراد ہے ۔ اس وقت رسول کریم صلی اللہ علیہ وسلم کے ساتھ بارہ صحابہ کے سوا اور کوئی بھی باقی نہ رہ گیا تھا ۔ آخر ہمارے ستر آدمی شہید ہو گئے ۔ بدر کی لڑائی میں آنحضرت صلی اللہ علیہ وسلم نے اپنے صحابہ کے ساتھ مشرکین کے ایک سو چالیس آدمیوں کا نقصان کیا تھا ‘ ستر ان میں سے قیدی تھے اور ستر مقتول ‘ ( جب جنگ ختم ہو گئی تو ایک پہاڑ پر کھڑے ہو کر ) ابوسفیان نے کہا کیا محمد صلی اللہ علیہ وسلم اپنی قوم کے ساتھ موجود ہیں ؟ تین مرتبہ انہوں نے یہی پوچھا ۔ لیکن نبی کریم صلی اللہ علیہ وسلم نے جواب دینے سے منع فرما دیا تھا ۔ پھر انہوں نے پوچھا ‘ کیا ابن ابی قحافہ ( ابوبکر رضی اللہ عنہ ) اپنی قوم میں موجود ہیں ؟ یہ سوال بھی تین مرتبہ کیا ‘ پھر پوچھا ابن خطاب ( عمر رضی اللہ عنہ ) اپنی قوم میں موجود ہیں ؟ یہ بھی تین مرتبہ پوچھا ‘ پھر اپنے ساتھیوں کی طرف مڑ کر کہنے لگے کہ یہ تینوں قتل ہو چکے ہیں اس پر عمر رضی اللہ عنہ سے نہ رہا گیا اور آپ بول پڑے کہ اے خدا کے دشمن ! خدا گواہ ہے کہ تو جھوٹ بول رہا ہے جن کے تو نے ابھی نام لئے تھے وہ سب زندہ ہیں اور ابھی تیرا برا دن آنے والا ہے ۔ ابوسفیان نے کہا اچھا ! آج کا دن بدر کا بدلہ ہے ۔ اور لڑائی بھی ایک ڈول کی طرح ہے ( کبھی ادھر کبھی ادھر ) تم لوگوں کو اپنی قوم کے بعض لوگ مثلہ کئے ہوئے ملیں گے ۔ میں نے اس طرح کا کوئی حکم ( اپنے آدمیوں کو ) نہیں دیا تھا ‘ لیکن مجھے ان کا یہ عمل برا بھی نہیں معلوم ہوا ۔ اس کے بعد وہ فخر یہ رجز پڑھنے لگا ‘ ہبل ( بت کا نام ) بلند رہے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا تم لوگ اس کا جواب کیوں نہیں دیتے ۔ صحابہ رضی اللہ عنہم نے پوچھا ہم اس کے جواب میں کیا کہیں یا رسول اللہ ؟ آپ صلی اللہ علیہ وسلم نے فرمایا کہو کہ اللہ سب سے بلند اور سب سے بڑا بزرگ ہے ۔ ابوسفیان نے کہا ہمارا مددگار عزیٰ ( بت ) ہے اور تمہارا کوئی بھی نہیں ، آپ نے فرمایا ، جواب کیوں نہیں دیتے ، صحابہ نے عرض کیا ، یا رسول اللہ ! اس کا جواب کیا دیا جائے ؟ آنحضرت صلی اللہ علیہ وسلم نے فرمایا ‘ کہو کہ اللہ ہمارا حامی ہے اور تمہارا حامی کوئی نہیں ۔", "b:3207": "نبی کریم صلی اللہ علیہ وسلم نے فرمایا ۔ میں ایک دفعہ بیت اللہ کے قریب نیند اور بیداری کی درمیانی حالت میں تھا ، پھر آنحضرت صلی اللہ علیہ وسلم نے دو آدمیوں کے درمیان لیٹے ہوئے ایک تیسرے آدمی کا ذکر فرمایا ۔ اس کے بعد میرے پاس سونے کا ایک طشت لایا گیا ، جو حکمت اور ایمان سے بھرپور تھا ۔ میرے سینے کو پیٹ کے آخری حصے تک چاک کیا گیا ۔ پھر میرا پیٹ زمزم کے پانی سے دھویا گیا اور اسے حکمت اور ایمان سے بھر دیا گیا ۔ اس کے بعد میرے پاس ایک سواری لائی گئی ۔ سفید ، خچر سے چھوٹی اور گدھے سے بڑی یعنی براق ، میں اس پر سوار ہو کر جبرائیل علیہ السلام کے ساتھ چلا ۔ جب ہم آسمان دنیا پر پہنچے تو پوچھا گیا کہ یہ کون صاحب ہیں ؟ انہوں نے کہا کہ جبرائیل ۔ پوچھا گیا کہ آپ کے ساتھ اور کون صاحب آئے ہیں ؟ انہوں نے بتایا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کہ کیا انہیں بلانے کے لیے آپ کو بھیجا گیا تھا ؟ انہوں نے کہا کہ ہاں ، اس پر جواب آیا کہ اچھی کشادہ جگہ آنے والے کیا ہی مبارک ہیں ، پھر میں آدم علیہ السلام کی خدمت میں حاضر ہوا ۔ اور انہیں سلام کیا ۔ انہوں نے فرمایا ، آو پیارے بیٹے اور اچھے نبی ۔ اس کے بعد ہم دوسرے آسمان پر پہنچے یہاں بھی وہی سوال ہوا ۔ کون صاحب ہیں ؟ کہا جبرائیل ، سوال ہوا ، آپ کے ساتھ کوئی اور صاحب بھی آئے ہیں ؟ کہا کہ محمد صلی اللہ علیہ وسلم ، سوال ہوا انہیں بلانے کے لیے آپ کو بھیجا گیا تھا ؟ کہا کہ ہاں ۔ اب ادھر سے جواب آیا ، اچھی کشادہ جگہ آئے ہیں ، آنے والے کیا ہی مبارک ہیں ۔ اس کے بعد میں عیسیٰ اور یحییٰ علیہ السلام سے ملا ، ان حضرات نے بھی خوش آمدید ، مرحبا کہا اپنے بھائی اور نبی کو ۔ پھر ہم تیسرے آسمان پر آئے یہاں بھی سوال ہوا کون صاحب ہیں ؟ جواب ملا جبرائیل ، سوال ہوا ، آپ کے ساتھ بھی کوئی ہے ؟ کہا کہ محمد صلی اللہ علیہ وسلم ، سوال ہوا ، انہیں بلانے کے لیے آپ کو بھیجا گیا تھا ؟ انہوں نے بتایا کہ ہاں ، اب آواز آئی اچھی کشادہ جگہ آئے آنے والے کیا ہی صالح ہیں ، یہاں یوسف علیہ السلام سے میں ملا اور انہیں سلام کیا ، انہوں نے فرمایا ، اچھی کشادہ جگہ آئے ہو میرے بھائی اور نبی ، یہاں سے ہم چوتھے آسمان پر آئے اس پر بھی یہی سوال ہوا ، کون صاحب ، جواب دیا کہ جبرائیل ، سوال ہوا ، آپ کے ساتھ اور کون صاحب ہیں ؟ کہا کہ محمد صلی اللہ علیہ وسلم ہیں ۔ پوچھا کیا انہیں لانے کے لیے آپ کو بھیجا گیا تھا ، جواب دیا کہ ہاں ، پھر آواز آئی ، اچھی کشادہ جگہ آئے کیا ہی اچھے آنے والے ہیں ۔ یہاں میں ادریس علیہ السلام سے ملا اور سلام کیا ، انہوں نے فرمایا ، مرحبا ، بھائی اور نبی ۔ یہاں سے ہم پانچویں آسمان پر آئے ۔ یہاں بھی سوال ہوا کہ کون صاحب ؟ جواب دیا کہ جبرائیل ، پوچھا گیا اور آپ کے ساتھ اور کون صاحب آئے ہیں ؟ جواب دیا کہ محمد صلی اللہ علیہ وسلم ، پوچھا گیا ، انہیں بلانے کے لیے بھیجا گیا تھا ؟ کہا کہ ہاں ، آواز آئی ، اچھی کشادہ جگہ آئے ہیں ۔ آنے والے کیا ہی اچھے ہیں ۔ یہاں ہم ہارون علیہ السلام سے ملے اور میں نے انہیں سلام کیا ۔ انہوں نے فرمایا ، مبارک میرے بھائی اور نبی ، تم اچھی کشادہ جگہ آئے ، یہاں سے ہم چھٹے آسمان پر آئے ، یہاں بھی سوال ہوا ، کون صاحب ؟ جواب دیا کہ جبرائیل ، پوچھا گیا ، آپ کے ساتھ اور بھی کوئی ہیں ؟ کہا کہ ہاں محمد صلی اللہ علیہ وسلم ہیں ۔ پوچھا گیا ، کیا انہیں بلایاگیا تھا کہا ہاں ، کہا اچھی کشادہ جگہ آئے ہیں ، اچھے آنے والے ہیں ۔ یہاں میں موسیٰ علیہ السلام سے ملا اور انہیں سلام کیا ۔ انہوں نے فرمایا ، میرے بھائی اور نبی اچھی کشادہ جگہ آئے ، جب میں وہاں سے آگے بڑھنے لگا تو وہ رونے لگے کسی نے پوچھا بزرگوار آپ کیوں رو رہے ہیں ؟ انہوں نے فرمایا کہ اے اللہ ! یہ نوجوان جسے میرے بعد نبوت دی گئی ، اس کی امت میں سے جنت میں داخل ہونے والے ، میری امت کے جنت میں داخل ہونے والے لوگوں سے زیادہ ہوں گے ۔ اس کے بعد ہم ساتویں آسمان پر آئے یہاں بھی سوال ہوا کہ کون صاحب ہیں ؟ جواب دیا کہ جبرائیل ، سوال ہوا کہ کوئی صاحب آپ کے ساتھ بھی ہیں ؟ جواب دیا کہ محمد صلی اللہ علیہ وسلم پوچھا ، انہیں بلانے کے لیے آپ کو بھیجا گیا تھا ؟ مرحبا ، اچھے آنے والے ۔ یہاں میں ابراہیم علیہ السلام سے ملا اور انہیں سلام کیا ۔ انہوں نے فرمایا میرے بیٹے اور نبی ، مبارک ، اچھی کشادہ جگہ آئے ہو ، اس کے بعد مجھے بیت المعمور دکھایا گیا ۔ میں نے جبرائیل علیہ السلام سے اس کے بارے میں پوچھا ، تو انہوں نے بتلایا کہ یہ بیت المعمور ہے ۔ اس میں ستر ہزار فرشتے روزانہ نماز پڑھتے ہیں ۔ اور ایک مرتبہ پڑھ کر جو اس سے نکل جاتا ہے تو پھر کبھی داخل نہیں ہوتا ۔ اور مجھے سدرۃالمنتہیٰ بھی دکھایا گیا ، اس کے پھل ایسے تھے جیسے مقام ہجر کے مٹکے ہوتے ہیں اور پتے ایسے تھے جیسے ہاتھی کے کان ، اس کی جڑ سے چار نہریں نکلتی تھیں ، دو نہریں تو باطنی تھیں اور دو ظاہری ، میں نے جبرائیل علیہ السلام سے پوچھا تو انہوں نے بتایا کہ جو دو باطنی نہریں ہیں وہ تو جنت میں ہیں اور دو ظاہری نہریں دنیا میں نیل اور فرات ہیں ، اس کے بعد مجھ پر پچاس وقت کی نمازیں فرض کی گئیں ۔ میں جب واپس ہوا اور موسیٰ علیہ السلام سے ملا تو انہوں نے پوچھا کہ کیا کر کے آئے ہو ؟ میں نے عرض کیا کہ پچاس نمازیں مجھ پر فرض کی گئی ہیں ۔ انہوں نے فرمایا کہ انسانوں کو میں تم سے زیادہ جانتا ہوں ، بنی اسرائیل کا مجھے برا تجربہ ہو چکا ہے ۔ تمہاری امت بھی اتنی نمازوں کی طاقت نہیں رکھتی ، اس لیے اپنے رب کی بارگاہ میں دوبارہ حاضری دو ، اور کچھ تخفیف کی درخواست کرو ، میں واپس ہوا تو اللہ تعالیٰ نے نمازیں چالیس وقت کی کر دیں ۔ پھر بھی موسیٰ علیہ السلام اپنی بات ( یعنی تخفیف کرانے ) پر مصر رہے ۔ اس مرتبہ تیس وقت کی رہ گئیں ۔ پھر انہوں نے وہی فرمایا اور اس مرتبہ بارگاہ رب العزت میں میری درخواست کی پیشی پر اللہ تعالیٰ نے انہیں دس کر دیا ۔ میں جب موسیٰ علیہ السلام کے پاس آیا تو اب بھی انہوں نے کم کرانے کے لیے اپنا اصرار جاری رکھا ۔ اور اس مرتبہ اللہ تعالیٰ نے پانچ وقت کی کر دیں ۔ اب موسیٰ علیہ السلام سے ملا ، تو انہوں نے پھر دریافت فرمایا کہ کیا ہوا ؟ میں نے کہا کہ اللہ تعالیٰ نے پانچ کر دی ہیں ۔ اس مرتبہ بھی انہوں نے کم کرانے کا اصرار کیا ۔ میں نے کہا کہ اب تو میں اللہ کے سپرد کر چکا ۔ پھر آواز آئی ۔ میں نے اپنا فریضہ ( پانچ نمازوں کا ) جاری کر دیا ۔ اپنے بندوں پر تخفیف کر چکا اور میں ایک نیکی کا بدلہ دس گنا دیتا ہوں ۔ اور ہمام نے کہا ، ان سے قتادہ نے کہا ، ان سے حسن نے ، ان سے ابوہریرہ رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم سے بیت المعمور کے بارے میں الگ روایت کی ہے ۔", "b:3231": "انہوں نے نبی کریم صلی اللہ علیہ وسلم سے پوچھا ، کیا آپ پر کوئی دن احد کے دن سے بھی زیادہ سخت گزرا ہے ؟ آپ صلی اللہ علیہ وسلم نے اس پر فرمایا کہ تمہاری قوم ( قریش ) کی طرف سے میں نے کتنی مصیبتیں اٹھائی ہیں لیکن اس سارے دور میں عقبہ کا دن مجھ پر سب سے زیادہ سخت تھا یہ وہ موقع تھا جب میں نے ( طائف کے سردار ) کنانہ بن عبد یالیل بن عبد کلال کے ہاں اپنے آپ کو پیش کیا تھا ۔ لیکن اس نے ( اسلام کو قبول نہیں کیا اور ) میری دعوت کو رد کر دیا ۔ میں وہاں سے انتہائی رنجیدہ ہو کر واپس ہوا ۔ پھر جب میں قرن الثعالب پہنچا ، تب مجھ کو کچھ ہوش آیا ، میں نے اپنا سر اٹھایا تو کیا دیکھتا ہوں کہ بدلی کا ایک ٹکڑا میرے اوپر سایہ کئے ہوئے ہے اور میں نے دیکھا کہ حضرت جبرائیل علیہ السلام اس میں موجود ہیں ، انہوں نے مجھے آواز دی اور کہا کہ اللہ تعالیٰ آپ کے بارے میں آپ کی قوم کی باتیں سن چکا اور جو انہوں نے رد کیا ہے وہ بھی سن چکا ۔ آپ کے پاس اللہ تعالیٰ نے پہاڑوں کا فرشتہ بھیجا ہے ، آپ ان کے بارے میں جو چاہیں اس کا اسے حکم دے دیں ۔ اس کے بعد مجھے پہاڑوں کے فرشتے نے آواز دی ، انہوں نے مجھے سلام کیا اور کہا کہ اے محمد صلی اللہ علیہ وسلم ! پھر انہیں نے بھی وہی بات کہی ، آپ جو چاہیں ( اس کا مجھے حکم فرمائیں ) اگر آپ چاہیں تو میں دونوں طرف کے پہاڑ ان پر لا کر ملا دوں ( جن سے وہ چکنا چور ہو جائیں ) نبی کریم صلی اللہ علیہ وسلم نے فرمایا ، مجھے تو اس کی امید ہے کہ اللہ تعالیٰ ان کی نسل سے ایسی اولاد پیدا کرے گا جو اکیلے اللہ کی عبادت کرے گی ، اور اس کے ساتھ کسی کو شریک نہ ٹھہرائے گی ۔", "b:3432": "میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا ، آنحضرت صلی اللہ علیہ وسلم فرما رہے تھے کہ مریم بنت عمران ( اپنے زمانہ میں ) سب سے بہترین خاتون تھیں اور اس امت کی سب سے بہترین خاتون حضرت خدیجہ ہیں ( رضی اللہ عنہا ) ۔", "b:349": "آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ میرے گھر کی چھت کھول دی گئی ، اس وقت میں مکہ میں تھا ۔ پھر جبرائیل علیہ السلام اترے اور انھوں نے میرا سینہ چاک کیا ۔ پھر اسے زمزم کے پانی سے دھویا ۔ پھر ایک سونے کا طشت لائے جو حکمت اور ایمان سے بھرا ہوا تھا ۔ اس کو میرے سینے میں رکھ دیا ، پھر سینے کو جوڑ دیا ، پھر میرا ہاتھ پکڑا اور مجھے آسمان کی طرف لے کر چلے ۔ جب میں پہلے آسمان پر پہنچا تو جبرائیل علیہ السلام نے آسمان کے داروغہ سے کہا کھولو ۔ اس نے پوچھا ، آپ کون ہیں ؟ جواب دیا کہ جبرائیل ، پھر انھوں نے پوچھا کیا آپ کے ساتھ کوئی اور بھی ہے ؟ جواب دیا ، ہاں میرے ساتھ محمد ( صلی اللہ علیہ وسلم ) ہیں ۔ انھوں نے پوچھا کہ کیا ان کے بلانے کے لیے آپ کو بھیجا گیا تھا ؟ کہا ، جی ہاں ! پھر جب انھوں نے دروازہ کھولا تو ہم پہلے آسمان پر چڑھ گئے ، وہاں ہم نے ایک شخص کو بیٹھے ہوئے دیکھا ۔ ان کے داہنی طرف کچھ لوگوں کے جھنڈ تھے اور کچھ جھنڈ بائیں طرف تھے ۔ جب وہ اپنی داہنی طرف دیکھتے تو مسکرا دیتے اور جب بائیں طرف نظر کرتے تو روتے ۔ انھوں نے مجھے دیکھ کر فرمایا ، آؤ اچھے آئے ہو ۔ صالح نبی اور صالح بیٹے ! میں نے جبرائیل علیہ السلام سے پوچھا یہ کون ہیں ؟ انھوں نے کہا کہ یہ آدم علیہ السلام ہیں اور ان کے دائیں بائیں جو جھنڈ ہیں یہ ان کے بیٹوں کی روحیں ہیں ۔ جو جھنڈ دائیں طرف ہیں وہ جنتی ہیں اور بائیں طرف کے جھنڈ دوزخی روحیں ہیں ۔ اس لیے جب وہ اپنے دائیں طرف دیکھتے ہیں تو خوشی سے مسکراتے ہیں اور جب بائیں طرف دیکھتے ہیں تو ( رنج سے ) روتے ہیں ۔ پھر جبرائیل مجھے لے کر دوسرے آسمان تک پہنچے اور اس کے داروغہ سے کہا کہ کھولو ۔ اس آسمان کے داروغہ نے بھی پہلے کی طرح پوچھا پھر کھول دیا ۔ حضرت انس نے کہا کہ ابوذر نے ذکر کیا کہ آپ صلی اللہ علیہ وسلم یعنی نبی کریم صلی اللہ علیہ وسلم نے آسمان پر آدم ، ادریس ، موسیٰ ، عیسیٰ اور ابراہیم علیہم السلام کو موجود پایا ۔ اور ابوذر رضی اللہ عنہ نے ہر ایک کا ٹھکانہ نہیں بیان کیا ۔ البتہ اتنا بیان کیا کہ آنحضور صلی اللہ علیہ وسلم نے حضرت آدم کو پہلے آسمان پر پایا اور حضرت ابراہیم علیہ السلام کو چھٹے آسمان پر ۔ انس نے بیان کیا کہ جب جبرائیل علیہ السلام نبی کریم صلی اللہ علیہ وسلم کے ساتھ ادریس علیہ السلام پر گزرے ۔ تو انھوں نے فرمایا کہ آؤ اچھے آئے ہو صالح نبی اور صالح بھائی ۔ میں نے پوچھا یہ کون ہیں ؟ جواب دیا کہ یہ ادریس علیہ السلام ہیں ۔ پھر موسیٰ علیہ السلام تک پہنچا تو انھوں نے فرمایا آؤ اچھے آئے ہو صالح نبی اور صالح بھائی ۔ میں نے پوچھا یہ کون ہیں ؟ جبرائیل علیہ السلام نے بتایا کہ موسیٰ علیہ السلام ہیں ۔ پھر میں عیسیٰ علیہ السلام تک پہنچا ، انھوں نے کہا آؤ اچھے آئے ہو صالح نبی اور صالح بھائی ۔ میں نے پوچھا یہ کون ہیں ؟ جبرائیل علیہ السلام نے بتایا کہ یہ عیسیٰ علیہ السلام ہیں ۔ پھر میں ابراہیم علیہ السلام تک پہنچا ۔ انھوں نے فرمایا آؤ اچھے آئے ہو صالح نبی اور صالح بیٹے ۔ میں نے پوچھا یہ کون ہیں ؟ جبرائیل علیہ السلام نے بتایا کہ یہ حضرت ابراہیم علیہ السلام ہیں ۔ ابن شہاب نے کہا کہ مجھے ابوبکر بن حزم نے خبر دی کہ عبداللہ بن عباس اور ابوحبۃ الانصاری رضی اللہ عنہم کہا کرتے تھے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ، پھر مجھے جبرائیل علیہ السلام لے کر چڑھے ، اب میں اس بلند مقام تک پہنچ گیا جہاں میں نے قلم کی آواز سنی ( جو لکھنے والے فرشتوں کی قلموں کی آواز تھی ) ابن حزم نے ( اپنے شیخ سے ) اور انس بن مالک نے ابوذر رضی اللہ عنہ سے نقل کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا ۔ پس اللہ تعالیٰ نے میری امت پر پچاس وقت کی نمازیں فرض کیں ۔ میں یہ حکم لے کر واپس لوٹا ۔ جب موسیٰ علیہ السلام تک پہنچا تو انھوں نے پوچھا کہ آپ کی امت پر اللہ نے کیا فرض کیا ہے ؟ میں نے کہا کہ پچاس وقت کی نمازیں فرض کی ہیں ۔ انھوں نے فرمایا آپ واپس اپنے رب کی بارگاہ میں جائیے ۔ کیونکہ آپ کی امت اتنی نمازوں کو ادا کرنے کی طاقت نہیں رکھتی ہے ۔ میں واپس بارگاہ رب العزت میں گیا تو اللہ نے اس میں سے ایک حصہ کم کر دیا ، پھر موسیٰ علیہ السلام کے پاس آیا اور کہا کہ ایک حصہ کم کر دیا گیا ہے ، انھوں نے کہا کہ دوبارہ جائیے کیونکہ آپ کی امت میں اس کے برداشت کی بھی طاقت نہیں ہے ۔ پھر میں بارگاہ رب العزت میں حاضر ہوا ۔ پھر ایک حصہ کم ہوا ۔ جب موسیٰ علیہ السلام کے پاس پہنچا تو انھوں نے فرمایا کہ اپنے رب کی بارگاہ میں پھر جائیے ، کیونکہ آپ کی امت اس کو بھی برداشت نہ کر سکے گی ، پھر میں باربار آیا گیا پس اللہ تعالیٰ نے فرمایا کہ یہ نمازیں ( عمل میں ) پانچ ہیں اور ( ثواب میں ) پچاس ( کے برابر ) ہیں ۔ میری بات بدلی نہیں جاتی ۔ اب میں موسیٰ علیہ السلام کے پاس آیا تو انھوں نے پھر کہا کہ اپنے رب کے پاس جائیے ۔ لیکن میں نے کہا مجھے اب اپنے رب سے شرم آتی ہے ۔ پھر جبرائیل مجھے سدرۃالمنتہیٰ تک لے گئے جسے کئی طرح کے رنگوں نے ڈھانک رکھا تھا ۔ جن کے متعلق مجھے معلوم نہیں ہوا کہ وہ کیا ہیں ۔ اس کے بعد مجھے جنت میں لے جایا گیا ، میں نے دیکھا کہ اس میں موتیوں کے ہار ہیں اور اس کی مٹی مشک کی ہے ۔", "b:371": "نبی کریم صلی اللہ علیہ وسلم غزوہ خبیر میں تشریف لے گئے ۔ ہم نے وہاں فجر کی نماز اندھیرے ہی میں پڑھی ۔ پھر نبی کریم صلی اللہ علیہ وسلم سوار ہوئے ۔ اور ابوطلحہ بھی سوار ہوئے ۔ میں ابوطلحہ کے پیچھے بیٹھا ہوا تھا ۔ نبی کریم صلی اللہ علیہ وسلم نے اپنی سواری کا رخ خیبر کی گلیوں کی طرف کر دیا ۔ میرا گھٹنا نبی کریم صلی اللہ علیہ وسلم کی ران سے چھو جاتا تھا ۔ پھر نبی کریم صلی اللہ علیہ وسلم نے اپنی ران سے تہبند کو ہٹایا ۔ یہاں تک کہ میں نبی کریم صلی اللہ علیہ وسلم کی شفاف اور سفید رانوں کی سفیدی اور چمک دیکھنے لگا ۔ جب آپ خیبر کی بستی میں داخل ہوئے ، تو آپ صلی اللہ علیہ وسلم نے فرمایا «الله اكبر» اللہ سب سے بڑا ہے ، خیبر برباد ہو گیا ، جب ہم کسی قوم کے آنگن میں اتر جائیں تو ڈرائے ہوئے لوگوں کی صبح منحوس ہو جاتی ہے ۔ آپ نے یہ تین مرتبہ فرمایا ، اس نے کہا کہ خیبر کے یہودی لوگ اپنے کاموں کے لیے باہر نکلے ہی تھے کہ وہ چلا اٹھے محمد ( صلی اللہ علیہ وسلم ) آن پہنچے ۔ اور عبدالعزیز راوی نے کہا کہ بعض حضرت انس رضی اللہ عنہ سے روایت کرنے والے ہمارے ساتھیوں نے «والخميس‏» کا لفظ بھی نقل کیا ہے ( یعنی وہ چلا اٹھے کہ محمد صلی اللہ علیہ وسلم لشکر لے کر پہنچ گئے ) پس ہم نے خیبر لڑ کر فتح کر لیا اور قیدی جمع کئے گئے ۔ پھر دحیہ رضی اللہ عنہ آئے اور عرض کی کہ یا رسول اللہ ! قیدیوں میں سے کوئی باندی مجھے عنایت کیجیئے ، آپ صلی اللہ علیہ وسلم نے فرمایا کہ جاؤ کوئی باندی لے لو ۔ انھوں نے صفیہ بنت حیی کو لے لیا ۔ پھر ایک شخص نبی کریم صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا اور عرض کی یا رسول اللہ ! صفیہ جو قریظہ اور نضیر کے سردار کی بیٹی ہیں ، انہیں آپ نے دحیہ کو دے دیا ۔ وہ تو صرف آپ ہی کے لیے مناسب تھیں ۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا کہ دحیہ کو صفیہ کے ساتھ بلاؤ ، وہ لائے گئے ۔ جب نبی کریم صلی اللہ علیہ وسلم نے انہیں دیکھا تو فرمایا کہ قیدیوں میں سے کوئی اور باندی لے لو ۔ راوی نے کہا کہ پھر نبی کریم صلی اللہ علیہ وسلم نے صفیہ کو آزاد کر دیا اور انہیں اپنے نکاح میں لے لیا ۔ ثابت بنانی نے حضرت انس رضی اللہ عنہ سے پوچھا کہ ابوحمزہ ! ان کا مہر آنحضور صلی اللہ علیہ وسلم نے کیا رکھا تھا ؟ حضرت انس رضی اللہ عنہ نے فرمایا کہ خود انہیں کی آزادی ان کا مہر تھا اور اسی پر آپ نے نکاح کیا ۔ پھر راستے ہی میں ام سلیم رضی اللہ عنہا ( حضرت انس رضی اللہ عنہ کی والدہ ) نے انہیں دلہن بنایا اور نبی کریم صلی اللہ علیہ وسلم کے پاس رات کے وقت بھیجا ۔ اب نبی کریم صلی اللہ علیہ وسلم دولہا تھے ، اس لیے آپ صلی اللہ علیہ وسلم نے فرمایا کہ جس کے پاس بھی کچھ کھانے کی چیز ہو تو یہاں لائے ۔ آپ نے ایک چمڑے کا دسترخوان بچھایا ۔ بعض صحابہ کھجور لائے ، بعض گھی ، عبدالعزیز نے کہا کہ میرا خیال ہے حضرت انس رضی اللہ عنہ نے ستو کا بھی ذکر کیا ۔ پھر لوگوں نے ان کا حلوہ بنا لیا ۔ یہ رسول اللہ صلی اللہ علیہ وسلم کا ولیمہ تھا ۔", "b:428": "جب نبی کریم صلی اللہ علیہ وسلم مدینہ تشریف لائے تو یہاں کے بلند حصہ میں بنی عمرو بن عوف کے یہاں آپ اترے اور یہاں چوبیس راتیں قیام فرمایا ۔ پھر آپ صلی اللہ علیہ وسلم نے بنونجار کو بلا بھیجا ، تو وہ لوگ تلواریں لٹکائے ہوئے آئے ۔ انس نے کہا ، گویا میری نظروں کے سامنے نبی کریم صلی اللہ علیہ وسلم اپنی سواری پر تشریف فرما ہیں ، جبکہ ابوبکر صدیق رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے پیچھے بیٹھے ہوئے ہیں اور بنو نجار کے لوگ آپ صلی اللہ علیہ وسلم کے چاروں طرف ہیں ۔ یہاں تک کہ آپ صلی اللہ علیہ وسلم ابوایوب کے گھر کے سامنے اترے اور آپ صلی اللہ علیہ وسلم یہ پسند کرتے تھے کہ جہاں بھی نماز کا وقت آ جائے فوراً نماز ادا کر لیں ۔ آپ بکریوں کے باڑوں میں بھی نماز پڑھ لیتے تھے ، پھر آپ نے یہاں مسجد بنانے کے لیے حکم فرمایا ۔ چنانچہ بنو نجار کے لوگوں کو آپ صلی اللہ علیہ وسلم نے بلوا کر فرمایا کہ اے بنو نجار ! تم اپنے اس باغ کی قیمت مجھ سے لے لو ۔ انھوں نے جواب دیا نہیں یا رسول اللہ ! اس کی قیمت ہم صرف اللہ سے مانگتے ہیں ۔ انس رضی اللہ عنہ نے بیان کیا کہ میں جیسا کہ تمہیں بتا رہا تھا یہاں مشرکین کی قبریں تھیں ، اس باغ میں ایک ویران جگہ تھی اور کچھ کھجور کے درخت بھی تھے پس نبی کریم صلی اللہ علیہ وسلم نے مشرکین کی قبروں کو اکھڑوا دیا ویرانہ کو صاف اور برابر کرایا اور درختوں کو کٹوا کر ان کی لکڑیوں کو مسجد کے قبلہ کی جانب بچھا دیا اور پتھروں کے ذریعہ انہیں مضبوط بنا دیا ۔ صحابہ پتھر اٹھاتے ہوئے رجز پڑھتے تھے اور نبی کریم صلی اللہ علیہ وسلم بھی ان کے ساتھ تھے اور یہ کہہ رہے تھے کہ اے اللہ ! آخرت کے فائدہ کے علاوہ اور کوئی فائدہ نہیں پس انصار و مہاجرین کی مغفرت فرمانا ۔", "b:3559": "رسول اللہ صلی اللہ علیہ وسلم بدزبان اور لڑنے جھگڑنے والے نہیں تھے ۔ آپ فرمایا کرتے تھے کہ تم میں سب سے بہتر وہ شخص ہے جس کے اخلاق سب سے اچھے ہوں ( جو لوگوں سے کشادہ پیشانی سے پیش آئے )", "b:3560": "رسول اللہ صلی اللہ علیہ وسلم سے جب بھی دو چیزوں میں سے کسی ایک کے اختیار کرنے کے لیے کہا گیا تو آپ نے ہمیشہ اسی کو اختیار فرمایا جس میں آپ کو زیادہ آسانی معلوم ہوئی بشرطیکہ اس میں کوئی گناہ نہ ہو ۔ کیونکہ اگر اس میں گناہ کا کوئی شائبہ بھی ہوتا تو آپ اس سے سب سے زیادہ دور رہتے اور آنحضرت صلی اللہ علیہ وسلم نے اپنی ذات کے لیے کبھی کسی سے بد لہ نہیں لیا ۔ لیکن اگر اللہ کی حرمت کو کوئی توڑ تا تو آپ اس سے ضرور بدلہ لیتے تھے ۔", "b:3562": "رسول اللہ صلی اللہ علیہ وسلم پردہ نشیں کنواری لڑکیوں سے بھی زیادہ شرمیلے تھے ۔", "b:3624": "حضرت فاطمہ رضی اللہ عنہا آئیں ، ان کی چال میں نبی کریم صلی اللہ علیہ وسلم کی چال سے بڑی مشابہت تھی ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : بیٹی آو مرحبا ! اس کے بعد آپ نے انہیں اپنی دائیں طرف یا بائیں طرف بٹھایا ، پھر ان کے کان میں آپ نے چپکے سے کوئی بات کہی تو وہ رونے لگیں ، میں نے ان سے کہا کہ آپ روتی کیوں ہو ؟ پھر دوبارہ آنحضرت صلی اللہ علیہ وسلم نے ان کے کان میں کچھ کہا تو وہ ہنس دیں ۔ میں نے ان سے کہا آج غم کے فوراً بعد ہی خوشی کی جو کیفیت میں نے آپ کے چہرے پر دیکھی وہ پہلے کبھی نہیں دیکھی تھی ۔ پھر میں نے ان سے پوچھا کہ آنحضرت صلی اللہ علیہ وسلم نے کیا فرمایا تھا ؟ انہوں نے کہا جب تک رسول اللہ صلی اللہ علیہ وسلم زندہ ہیں میں آپ کے راز کو کسی پر نہیں کھول سکتی ۔ چنانچہ میں نے آپ کی وفات کے بعد پوچھا ۔ تو انہوں نے بتایا کہ آپ نے میرے کان میں کہا تھا کہ حضرت جبرائیل علیہ السلام ہر سال قرآن مجید کا ایک دور کیا کرتے تھے ، لیکن اس سال انہوں نے دو مرتبہ دور کیا ہے ، مجھے یقین ہے کہ اب میری موت قریب ہے اور میرے گھرانے میں سب سے پہلے مجھ سے آ ملنے والی تم ہو گی ۔ میں ( آپ کی اس خبر پر ) رونے لگی تو آپ نے فرمایا کہ تم اس پر راضی نہیں کہ جنت کی عورتوں کی سردار بنو گی یا ( آپ نے فرمایا کہ ) مومنہ عورتوں کی ، تو اس پر میں ہنسی تھی ۔", "b:3653": "جب ہم غار ثور میں چھپے تھے تو میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا کہ اگر مشرکین کے کسی آدمی نے اپنے قدموں پر نظر ڈالی تو وہ ضرور ہم کو دیکھ لے گا ۔ اس پر آنحضرت صلی اللہ علیہ وسلم نے فرمایا : اے ابوبکر ! ان دوکا کوئی کیا بگاڑ سکتا ہے جن کے ساتھ تیسرا اللہ تعالیٰ ہے ۔", "b:3656": "نبی کریم صلی اللہ علیہ وسلم نے فرمایا : اگر میں اپنی امت کے کسی فرد کو اپنا جانی دوست بنا سکتا تو ابوبکر کو بناتا لیکن وہ میرے دینی بھائی اور میرے ساتھی ہیں ۔", "b:3668": "آنحضرت صلی اللہ علیہ وسلم کی جب وفات ہوئی تو حضرت ابوبکر رضی اللہ اس وقت مقام سنح میں تھے ، اسماعیل نے کہا یعنی عوالی کے ایک گاؤں میں ۔ آپ کی خبر سن کر حضرت عمر اٹھ کریہ کہنے لگے کہ اللہ کی قسم رسول اللہ صلی اللہ علیہ وسلم کی وفات نہیں ہوئی ۔ حضرت عائشہ رضی اللہ عنہا نے کہا کہ حضرت عمر رضی اللہ عنہ کہا کرتے تھے اللہ کی قسم اس وقت میرے دل میں یہی خیال آتا تھا اور میں کہتاتھا کہ اللہ آپ کو ضرور اس بیماری سے اچھا کر کے اٹھائے گا اور آپ ان لوگوں کے ہاتھ اور پاؤں کاٹ دیں گے ( جو آپ کی موت کی باتیں کرتے ہیں ) اتنے میں حضرت ابوبکر رضی اللہ عنہ تشریف لے آئے اور اندر جا کر آپ کی نعش مبارک کے اوپر سے کپڑا اٹھایا اور بوسہ دیا اور کہا : میرے ماں باپ آپ پر فدا ہوں ۔ آپ زندگی میں بھی پاکیزہ تھے اور وفات کے بعد بھی اور اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ، اللہ تعالیٰ آپ پر دو مرتبہ موت ہرگز طاری نہیں کرے گا ۔ اس کے بعد آپ باہر آئے اور عمر رضی اللہ عنہ سے کہنے لگے اے قسم کھانے والے ! ذرا تامل کر ۔ پھر جب حضرت ابوبکر رضی اللہ عنہ نے گفتگو شروع کی تو حضرت عمر رضی اللہ عنہ خاموش بیٹھ گئے ۔ حضرت ابوبکر رضی اللہ عنہ نے پہلے اللہ کی حمد و ثنا بیان کی ۔ پھر فرمایا : لوگو ! دیکھو اگر کوئی محمد ( صلی اللہ علیہ وسلم ) کو پوجتا تھا ( یعنی یہ سمجھتا تھا کہ وہ آدمی نہیں ہیں ، وہ کبھی نہیں مریں گے ) تو اسے معلوم ہونا چاہیے کہ حضرت محمد صلی اللہ علیہ وسلم کی وفات ہو چکی ہے اور جو شخص اللہ کی پوجا کرتا تھا تو اللہ ہمیشہ زندہ ہے اسے موت کبھی نہیں آئے گی ۔ ( پھر ابوبکر رضی اللہ عنہ نے سورۃ الزمر کی یہ آیت پڑھی ) ” اے پیغبر ! توبھی مرنے والا ہے اور وہ بھی مریں گے “ اور اللہ تعالیٰ نے فرمایا کہ ” محمد صلی اللہ علیہ وسلم صرف ایک رسول ہیں ۔ اس سے پہلے بھی بہت سے رسول گزر چکے ہیں ۔ پس کیا اگر وہ وفات پا جائیں یا انہیں شہید کر دیا جائے تو تم اسلام سے پھر جاؤ گے اور جو شخص اپنی ایڑیوں کے بل پھر جائے تو وہ اللہ کو کوئی نقصان نہیں پہنچا سکے گا اور اللہ عنقریب شکرگزار بندوں کو بدلہ دینے والا ہے “ راوی نے بیان کیا کہ یہ سن کر لوگ پھوٹ پھوٹ کررونے لگے ۔ راوی نے بیان کیا کہ انصار سقیفہ بنی ساعدہ میں سعد بن عبادہ رضی اللہ عنہ کے پاس جمع ہو گئے اور کہنے لگے کہ ایک امیر ہم میں سے ہو گا اور ایک امیر تم ( مہاجرین ) میں سے ہو گا ( دونوں مل کر حکومت کریں گے ) پھر ابوبکر ، عمر بن خطاب اور ابوعبیدہ بن جراح رضی اللہ عنہم ان کی مجلس میں پہنچے ۔ عمر رضی اللہ عنہ نے گفتگو کرنی چاہی لیکن حضرت ابوبکر رضی اللہ عنہ نے ان سے خاموش رہنے کے لیے کہا ۔ عمر رضی اللہ عنہ کہا کرتے تھے کہ اللہ کی قسم میں نے ایسا صرف اس وجہ سے کیا تھا کہ میں نے پہلے ہی سے ایک تقریر تیار کر لی تھی جو مجھے بہت پسند آئی تھی پھر بھی مجھے ڈرتھا کہ ابوبکر رضی اللہ عنہ کی برابری اس سے بھی نہیں ہو سکے گی ۔ پھر حضرت ابوبکر رضی اللہ عنہ نے انتہائی بلاغت کے ساتھ بات شروع کی ۔ انہوں نے اپنی تقریر میں فرمایا کہ ہم ( قریش ) امراء ہیں اور تم ( جماعت انصار ) وزارء ہو ۔ اس پر حضرت حباب بن منذر رضی اللہ عنہ بولے کہ نہیں اللہ کی قسم ہم ایسا نہیں ہونے دیں گے ، ایک امیر ہم میں سے ہو گا اور ایک امیر تم میں سے ہو گا ۔ حضرت ابوبکر رضی اللہ عنہ نے فرمایا کہ نہیں ہم امراء ہیں تم وزارء ہو ( وجہ یہ ہے کہ ) قریش کے لوگ سارے عرب میں شریف خاندان شمار کیے جاتے ہیں اور ان کاملک ( یعنی مکہ ) عرب کے بیچ میں ہے تو اب تم کو اختیار ہے یا تو عمر رضی اللہ عنہ کی بیعت کر لو یا ابوعبیدہ بن جراح کی ۔ حضرت عمر رضی اللہ عنہ نے کہا : نہیں ہم آپ کی ہی بیعت کریں گے ۔ آپ ہمارے سردار ہیں ، ہم میں سب سے بہتر ہیں اور رسول کریم صلی اللہ علیہ وسلم کے نزدیک آپ ہم سب سے زیادہ محبوب ہیں ۔ حضرت عمر رضی اللہ عنہ نے ان کا ہاتھ پکڑ لیا اور ان کے ہاتھ پر بیعت کر لی پھر سب لوگوں نے بیعت کی ۔ اتنے میں کسی کی آواز آئی کہ سعد بن عبادہ رضی اللہ عنہ کو تم لوگوں نے مارڈالا ۔ عمر رضی اللہ عنہ نے کہا : انہیں اللہ نے مارڈالا ۔", "b:3683": "حضرت عمر رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اندر آنے کی اجازت چاہی ۔ اس وقت آپ کے پاس قریش کی چند عورتیں ( امہات المومین میں سے ) بیٹھی باتیں کر رہی تھیں اور آپ کی آوازپر اپنی آواز اونچی کرتے ہوئے آپ سے نان و نفقہ میں زیادتی کا مطالبہ کر رہی تھیں ، جوں ہی حضرت عمر رضی اللہ عنہ نے اجازت چاہی تو وہ تمام کھڑی ہو کر پردے کے پیچھے جلدی سے بھاگ کھڑی ہوئیں ۔ آخر آنحضرت صلی اللہ علیہ وسلم نے اجازت دی اور وہ داخل ہوئے تو آنحضرت صلی اللہ علیہ وسلم مسکرا رہے تھے ۔ حضرت عمر رضی اللہ عنہ نے عرض کیا : یا رسول اللہ ! اللہ تعالیٰ آپ صلی اللہ علیہ وسلم کو ہمیشہ خوش رکھے ۔ آپ صلی اللہ علیہ وسلم نے فرمایا : مجھے ان عورتوں پرہنسی آ رہی ہے جو ابھی میرے پاس بیٹھی ہوئی تھیں ، لیکن تمہاری آواز سنتے ہی سب پردے کے پیچھے بھاگ گئیں ۔ حضرت عمر رضی اللہ عنہ نے عرض کیا : یا رسول اللہ ! ڈرنا تو انہیں آپ سے چاہیے تھا ۔ پھرانہوں نے ( عورتوں سے ) کہا اے اپنی جانوں کی دشمنو ! تم مجھ سے تو ڈرتی ہو اور حضور اکرم صلی اللہ علیہ وسلم سے نہیں ڈرتیں ، عورتوں نے کہا کہ ہاں ، آپ ٹھیک کہتے ہیں ۔ حضور اکرم صلی اللہ علیہ وسلم کے مقابلے میں آپ کہیں زیادہ سخت ہیں ۔ اس پر آنحضرت صلی اللہ علیہ وسلم نے فرمایا : اے ابن خطاب ! اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ، اگر شیطان تمہیں کسی راستے پر چلتا دیکھتا ہے تو اسے چھوڑ کر وہ کسی دوسرے راستے پر چل پڑتا ہے ۔", "b:3701": "رسول اللہ صلی اللہ علیہ وسلم نے جنگ خیبر کے موقع پر بیان فرمایا کہ کل میں ایک ایسے شخص کو اسلامی علم دوں گا جس کے ہاتھ پر اللہ تعالیٰ فتح عنایت فرمائے گا ، راوی نے بیان کیا کہ رات کو لوگ یہ سوچتے رہے کہ دیکھئیے علم کسے ملتا ہے ، جب صبح ہوئی تو آنحضرت صلی اللہ علیہ وسلم کی خدمت میں سب حضرات ( جو سرکردہ تھے ) حاضر ہوئے ، سب کو امید تھی کہ علم انہیں ہی ملے گا ، لیکن حضور صلی اللہ علیہ وسلم نے دریافت فرمایا ، علی بن ابی طالب کہاں ہیں ؟ لوگوں نے بتایا کہ ان کی آنکھوں میں درد ہے ، حضور صلی اللہ علیہ وسلم نے فرمایا کہ پھر ان کے یہاں کسی کو بھیج کر بلوا لو ، جب وہ آئے تو آنحضرت صلی اللہ علیہ وسلم نے ان کی آنکھ میں اپنا تھوک ڈالا اور ان کے لیے دعا فرمائی ، اس سے انہیں ایسی شفاء حاصل ہوئی جیسے کوئی مرض پہلے تھا ہی نہیں ، چنانچہ آپ نے علم انہیں کو عنایت فرمایا ، حضرت علی رضی اللہ عنہ نے عرض کیا یا رسول اللہ ! میں ان سے اتنا لڑوں گا کہ وہ ہمارے جیسے ہو جائیں ( یعنی مسلمان بن جائیں ) آپ نے فرمایا : ابھی یوں ہی چلتے رہو ، جب ان کے میدان میں اترو تو پہلے انہیں اسلام کی دعوت دو اور انہیں بتاو کہ اللہ کے ان پر کیا حقوق واجب ہیں ، خدا کی قسم اگر تمہارے ذریعہ اللہ تعالیٰ ایک شخص کو بھی ہدایت دیدے تو وہ تمہارے لیے سرخ اونٹوں ( کی دولت ) سے بہتر ہے ۔", "b:3706": "نبی کریم صلی اللہ علیہ وسلم نے حضرت علی رضی اللہ عنہ سے فرمایا کہ کیا تم اس پر خوش نہیں ہو کہ تم میرے لیے ایسے ہو جیسے حضرت موسیٰ علیہ السلام کے لیے حضرت ہارون علیہ السلام تھے ۔", "b:3714": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : فاطمہ میرے جسم کا ٹکرا ہے ، اس لیے جس نے اسے ناحق ناراض کیا ، اس نے مجھے ناراض کیا ۔", "b:3728": "عرب میں سب سے پہلے اللہ کے راستے میں ، میں نے تیراندازی کی تھی ( ابتداء اسلام میں ) ہم نبی کریم صلی اللہ علیہ وسلم ، کے ساتھ اس طرح غزوات میں شرکت کرتے تھے کہ ہمارے پاس درخت کے پتوں کے سوا کھانے کے لیے کچھ بھی نہ ہوتا تھا ، اس سے ہمیں اونٹ اور بکریوں کی طرح اجابت ہوتی تھی ۔ یعنی ملی ہوئی نہیں ہوتی تھی ۔ لیکن اب بنی اسد کا یہ حال ہے کہ اسلامی احکام پر عمل میں میرے اندر عیب نکالتے ہیں ( اگر ) ایسا ہو تو میں بالکل محروم اور بے نصیب ہی رہا اور میرے سب کام برباد ہو گئے ۔ ہوایہ تھا کہ بنی اسد نے حضرت عمر رضی اللہ عنہ سے سعد رضی اللہ عنہ کی چغلی کھائی تھی ۔ یہ کہا تھا کہ وہ اچھی طرح نماز بھی نہیں پڑھتے ۔", "b:3744": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا : ہر امت میں امین ہوتے ہیں اور اس امت کے امین ابوعبیدہ بن جراح ہیں ۔ ( رضی اللہ عنہ و ارضاہ )", "b:3754": "ابوبکر رضی اللہ عنہ ہمارے سردار ہیں اور ہمارے سردار کو انہوں نے آزاد کیا ہے ، ان کی مراد حضرت بلا ل حبشی رضی اللہ عنہ سے تھی ۔", "b:3768": "رسول اللہ صلی اللہ علیہ وسلم نے ایک دن فرمایا : اے عائش یہ جبرائیل علیہ السلام تشریف فرما ہیں اور تمہیں سلام کہتے ہیں ، میں نے اس پر جواب دیا وعلیہ السلام ورحمۃ اللہ وبرکاتہ ، آپ وہ چیز ملاحظہ فرماتے ہیں جو مجھ کو نظر نہیں آتی ۔ ( آپ کی مراد نبی کریم صلی اللہ علیہ وسلم سے تھی ) ۔", "b:3770": "میں نے رسول کریم صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا ہے کہ عائشہ رضی اللہ عنہا کی فضیلت باقی عورتوں پر ایسی ہے جیسے ثرید کی فضیلت اور تمام کھانوں پر ۔", "b:3820": "جبرائیل علیہ السلام رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور کہا یا رسول اللہ صلی اللہ علیہ وسلم ! خدیجہ رضی اللہ عنہا آپ کے پاس ایک برتن لیے آ رہی ہیں جس میں سالن یا ( فرمایا ) کھانایا ( فرمایا ) پینے کی چیز ہے جب وہ آپ کے پاس آئیں تو ان کے رب کی جانب سے انہیں سلام پہنچا دیجئیے گا اور میری طرف سے بھی ! اور انہیں جنت میں موتیوں کے ایک محل کی بشارت دے دیجئیے گا ، جہاں نہ شور و ہنگامہ ہو گا اور نہ تکلیف و تھکن ہو گی ۔", "b:3886": "آپ صلی اللہ علیہ وسلم نے فرمایا تھا کہ جب قریش نے ( معراج کے واقعہ کے سلسلے میں ) مجھ کو جھٹلایا تو میں حطیم میں کھڑا ہو گیا اور اللہ تعالیٰ نے میرے لئے بیت المقدس کو روشن کر دیا اور میں نے اسے دیکھ کر قریش سے اس کے پتے اور نشان بیان کرنا شروع کر دیئے ۔", "b:3887": "نبی کریم صلی اللہ علیہ وسلم نے ان سے شب معراج کا واقعہ بیان کیا ، آپ صلی اللہ علیہ وسلم نے فرمایا کہ میں حطیم میں لیٹا ہوا تھا ۔ بعض دفعہ قتادہ نے حطیم کے بجائے حجر بیان کیا کہ میرے پاس ایک صاحب ( جبرائیل علیہ السلام ) آئے اور میر ا سینہ چاک کیا ، قتادہ نے بیان کیا کہ میں نے حضرت انس رضی اللہ عنہ سے سنا ، وہ بیان کرتے تھے کہ یہاں سے یہاں تک ۔ میں نے جارود سے سنا جو میرے قریب ہی بیٹھے تھے ۔ پوچھا کہ حضرت انس رضی اللہ عنہ کی اس لفظ سے کیا مراد تھی ؟ تو انہوں نے کہا کہ حلق سے ناف تک چاک کیا ( قتادہ نے بیان کیا کہ ) میں نے حضرت انس سے سنا ، انہوں نے بیان کیا کہ آنحضرت صلی اللہ علیہ وسلم کے سینے کے اوپر سے ناف تک چاک کیا ، پھر میرا دل نکالا اور ایک سونے کا طشت لایا گیا جو ایمان سے بھرا ہوا تھا ، اس سے میرا دل دھویا گیا اور پہلے کی طرح رکھ دیا گیا ۔ اس کے بعدایک جانور لایا گیا جو گھوڑے سے چھوٹا اور گدھے سے بڑا تھا اور سفید ! جارود نے حضرت انس رضی اللہ عنہ سے پوچھا ابوحمزہ ! کیا وہ براق تھا ؟ آپ نے فرمایا کہ ہاں ۔ اس کا ہر قدم اس کے منتہائے نظر پر پڑتا تھا ( آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ ) مجھے اس پر سوار کیا گیا اور جبرائیل ۔ مجھے لے کر چلے آسمان دنیا پر پہنچے تو دروازہ کھلوایا ، پوچھا گیا کون صاحب ہیں ؟ انہوں نے بتایا کہ جبرائیل ( علیہ السلام ) پوچھا گیا اور آپ کے ساتھ کون ہے ؟ آپ نے بتایا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا ، کیا انہیں بلانے کے لئے آپ کو بھیجا گیا تھا ؟ انہوں نے جواب دیا کہ ہاں ۔ اس پر آواز آئی انہیں خوش آمدید ! کیا ہی مبارک آنے والے ہیں وہ ۔ اور دروازہ کھول دیا ۔ جب میں اندر گیا تو میں نے وہاں آدم علیہ السلام کو دیکھا ، جبرائیل علیہ السلام نے فرمایا یہ آپ کے جد امجد آدم علیہ السلام ہیں ، انہیں سلام کیجئے ۔ میں نے ان کو سلام کیا اور انہوں نے جواب دیا اور فرمایا خوش آمدید نیک بیٹے اور نیک نبی ! جبرائیل علیہ السلام اوپر چڑھے اور دوسرے آسمان پر آئے وہاں بھی دروازہ کھلوایا آواز آئی کون صاحب آئے ہیں ؟ بتایا کہ جبرائیل ( علیہ السلام ) پوچھا گیا آپ کے ساتھ اور کوئی صاحب بھی ہیں ؟ کہا محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کیا آپ کو انہیں بلانے کے لئے بھیجا گیا تھا ؟ انہوں نے جواب دیا کہ ہاں ، پھر آواز آئی انہیں خوش آمدید ۔ کیا ہی اچھے آنے والے ہیں وہ ۔ پھر دروازہ کھلا اور میں اندر گیا تو وہاں یحییٰ اور عیسیٰ علیہما السلام موجود تھے ۔ یہ دونوں خالہ زاد بھائی ہیں ۔ جبرائیل علیہ السلام نے فرمایا یہ عیسیٰ اور یحییٰ علیہما السلام ہیں ، انہیں سلام کیجئے میں نے سلام کیا اور ان حضرات نے میرے سلام کا جواب دیا اور فرمایا خوش آمدید نیک نبی اور نیک بھائی ! یہاں سے جبرائیل علیہ السلام مجھے تیسرے آسمان کی طرف لے کر چڑھے اور دروازہ کھلوایا ۔ پوچھا گیا کون صاحب آئے ہیں ؟ جواب دیا کہ جبرائیل ۔ پوچھا گیا اور آپ کے ساتھ کون صاحب آئے ہیں ؟ جواب دیا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کیا انہیں لانے کے لئے آپ کو بھیجا گیا تھا ؟ جواب دیا کہ ہاں ۔ اس پر آواز آئی انہیں خوش آمدید ۔ کیا ہی اچھے آنے والے ہیں وہ ، دروازہ کھلااور جب میں اندر داخل ہوا تو وہاں یوسف علیہ السلام موجود تھے ۔ جبرائیل علیہ السلام نے فرمایا یہ یوسف ہیں انہیں سلام کیجئے میں نے سلام کیا تو انہوں نے جواب دیا اور فرمایا خوش آمدید نیک نبی اور نیک بھائی ! پھر حضرت جبرائیل علیہ السلام مجھے لے کر اوپر چڑھے اور چوتھے آسمان پر پہنچے دروازہ کھلوایا تو پوچھا گیا کون صاحب ہیں ؟ بتایا کہ جبرائیل ! پوچھا گیا اور آپ کے ساتھ کون ہے ؟ کہا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کیاانہیں بلانے کے لئے آپ کو بھیجاگیا تھا ؟ جواب دیا کہ ہاں کہا کہ انہیں خوش آمدید کیا ہی اچھے آنے والے ہیں وہ ! اب دروازہ کھلا جب میں وہاںادریس علیہ السلام کی خدمت میں پہنچا تو جبرائیل علیہ السلام نے فرمایا یہ ادریس علیہ السلام ہیں انہیں سلام کیجئے میں نے انہیں سلام کیا اور انہوں نے جواب دیا اور فرمایا خوش آمدید پاک بھائی اور نیک نبی ۔ پھر مجھے لے کر پانچویں آسمان پر آئے اور دروازہ کھلوایا پوچھا گیا کون صاحب ہیں ؟ جواب دیا کہ جبرائیل ، پوچھا گیا آپ کے ساتھ کون صاحب آئے ہیں ؟ جواب دیا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کہ انہیں بلانے کے لئے آپ کو بھیجا گیا تھا ؟ جواب دیا کہ ہاں اب آواز آئی خوش آمدید کیا ہی اچھے آنے والے ہیں وہ ، یہاں جب میں ہارون علیہ السلام کی خدمت میں حاضر ہوا تو جبرائیل علیہ السلام نے بتایا کہ یہ ہارون ہیں انہیں سلام کیجئے میں نے انہیں سلام کیا انہوں نے جواب کے بعد فرمایا خوش آمدید نیک نبی اور نیک بھائی ! یہاں سے لے کر مجھے آگے بڑھے اور چھٹے آسمان پر پہنچے اور دروازہ کھلوایا پوچھا گیا کون صاحب آئے ہیں ؟ بتایا کہ جبرائیل ، پوچھا گیا آپ کے ساتھ کوئی دوسرے صاحب بھی آئے ہیں ؟ جواب دیا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کیا انہیں بلانے کے لئے آپ کو بھیجا گیا تھا ؟ جواب دیا کہ ہاں ۔ پھر کہا انہیں خوش آمدید کیا ہی اچھے آنے والے ہیں وہ ۔ میں جب وہاں موسیٰ علیہ السلام کی خدمت میں حاضر ہوا تو جبرائیل علیہ السلام نے فرمایا کہ یہ موسیٰ علیہ السلام ہیں انہیں سلام کیجئے ، میں نے سلام کیا اور انہوں نے جواب کے بعد فرمایا خوش آمدید نیک نبی اور نیک بھائی ! جب میں آگے بڑھا تو وہ رونے لگے کسی نے پوچھا آپ روکیوں رہے ہیں ؟ تو انہوں نے فرمایا میں اس پر رورہا ہوں کہ یہ لڑکا میرے بعد نبی بنا کر بھیجا گیا لیکن جنت میں اس کی امت کے لوگ میری امت سے زیادہ ہوں گے ۔ پھر جبرائیل علیہ السلام مجھے لے کر ساتویں آسمان کی طرف گئے اور دروازہ کھلوایا ۔ پوچھا گیا کون صاحب آئے ہیں ؟ جواب دیا کہ جبرائیل ۔ پوچھا گیا اور آپ کے ساتھ کون صاحب آئے ہیں ؟ جواب دیا کہ محمد ( صلی اللہ علیہ وسلم ) پوچھا گیا کیا انہیں بلانے کے لئے آپ کو بھیجا گیا تھا ؟ جواب دیا کہ ہاں ۔ کہا کہ انہیں خوش آمدید ، کیا ہی اچھے آنے والے ہیں وہ ، میں جب اندر گیا تو ابراہیم علیہ السلام تشریف رکھتے تھے ۔ جبرائیل علیہ السلام نے فرمایا کہ یہ آپ کے جد امجد ہیں ، انہیں سلام کیجئے ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ میں نے ان کو سلام کیا تو انہوں نے جواب دیا اور فرمایاخوش آمدید نیک نبی اور نیک بیٹے ! پھر سدرۃالمنتہیٰ کو میرے سامنے کر دیا گیا میں نے دیکھا کہ اس کے پھل مقام حجر کے مٹکوں کی طرح ( بڑے بڑے ) تھے اور اس کے پتے ہاتھیوں کے کان کی طرح تھے ۔ جبرائیل علیہ السلام نے فرمایا کہ یہ سدرۃالمنتہیٰ ہے ۔ وہاں میں نے چار نہریں دیکھیں دو باطنی اور دو ظاہری ۔ میں نے پوچھا اے جبرائیل علیہ السلام ! یہ کیا ہیں ؟ انہوں نے بتایا کہ جو دوباطنی نہریں ہیں وہ جنت سے تعلق رکھتی ہیں اور دوظاہری نہریں نیل اور فرات ہیں ۔ پھر میرے سامنے بیت المعمور کو لایا گیا ، وہاں میرے سامنے ایک گلاس میں شراب ایک میں دودھ اور ایک میں شہد لایا گیا ۔ میں نے دودھ کا گلاس لے لیا تو جبرائیل علیہ السلام نے فرمایا یہی فطرت ہے اور آپ اس پر قائم ہیں اور آپ کی امت بھی ! پھر مجھ پر روزانہ پچاس نمازیں فرض کی گئیں میں واپس ہوا اور موسیٰ علیہ السلام کے پاس سے گزراتو انہوں نے پوچھا کس چیز کا آپ کو حکم ہوا ؟ میں نے کہا کہ روزانہ پچاس وقت کی نماز وں کا ، موسیٰ علیہ السلام نے فرمایا لیکن آپ کی امت میں اتنی طاقت نہیں ہے ۔ اس سے پہلے میرا واسطہ لوگوں سے پڑچکا ہے اور بنی اسرائیل کا مجھے تلخ تجربہ ہے ۔ اس لئے آپ اپنے رب کے حضور میں دوبارہ جائیے اور اپنی امت پر تخفیف کے لئے عرض کیجئے ۔ چنانچہ میں اللہ تعالیٰ کے دربار میں دوبارہ حاضر ہوا اور تخفیف کے لئے عرض کی تو دس وقت کی نمازیں کم کر دی گئیں ۔ پھر میں جب واپسی میں موسیٰ علیہ السلام کے پاس سے گزرا تو انہوں نے پھر وہی سوال کیا میں دوبارہ بارگاہ رب تعالیٰ میں حاضر ہوا اور اس مرتبہ بھی دس وقت کی نمازیں کم ہوئیں ۔ پھر میں موسیٰ علیہ السلام کے پاس سے گزرا اور تو انہوں نے وہی مطالبہ کیا میں نے اس مرتبہ بھی بار گاہ رب تعالیٰ میں حاضر ہو کر دس وقت کی نمازیں کم کرائیں ، موسٰی علیہ السلام کے پاس سے پھر گزرا انہوں نے اپنی رائے کا اظہار کیا پھر بارگاہ الٰہی میں حاضر ہوا تو مجھے دس وقت کی نمازوں کا حکم ہوا میں واپس ہونے لگا تو آپ نے پھر وہی کہا اب بارگاہ الٰہی میں حاضرہو اتو روزانہ صرف پانچ وقت کی نمازوں کا حکم باقی رہا ۔ موسیٰ علیہ السلام کے پاس آیا تو آپ نے دریافت فرمایا اب کیاحکم ہوا ؟ میں نے حضرت موسیٰ علیہ السلام کو بتایا کہ روزانہ پانچ وقت کی نمازوں کا حکم ہوا ہے ۔ فرمایا کہ آپ کی امت اس کی بھی طاقت نہیں رکھتی میرا واسطہ آپ سے پہلے لوگوں سے پڑ چکا ہے اور بنی اسرائیل کا مجھے تلخ تجربہ ہے ۔ اپنے رب کے دربار میں پھر حاضر ہو کر تخفیف کے لئے عرض کیجئے ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا رب تعالیٰ سے میں بہت سوال کر چکا اور اب مجھے شرم آتی ہے ۔ اب میں بس اسی پر راضی ہوں ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ پھر جب میں وہاں سے گزرنے لگا تو ندا آئی ” میں نے اپنا فریضہ جاری کر دیا اور اپنے بندوں پر تخفیف کر چکا ۔ “", "b:3888": "اللہ کے ارشاد وما جعلنا الرؤيا التي أريناك إلا فتنۃ للناس‏ ( اور جو خواب ہم نے آپ کو دکھایا اس سے مقصد صرف لوگوں کا امتحان تھا ) فرمایا کہ اس میں رؤیا سے آنکھ سے دیکھنا ہی مراد ہے ۔ جو رسول اللہ صلی اللہ علیہ وسلم کو اس معراج کی رات میں د کھایا گیا تھا جس میں آپ کو بیت المقدس تک لے جایا گیا تھا اور قرآن مجید میں ” الشجرۃ الملعونۃ “ کا ذکر آیا ہے وہ تھوہڑ کا درخت ہے ۔", "b:3902": "نبی کریم صلی اللہ علیہ وسلم کو چالیس سال کی عمر میں رسول بنایا گیا تھا ۔ پھر آپ پر مکہ مکرمہ میں تیرہ سال تک وحی آتی رہی اس کے بعد آپ کو ہجرت کا حکم ہوا اور آپ نے ہجرت کی حالت میں دس سال گزارے ، ( مدینہ میں ) جب آپ کی وفات ہوئی تو آپ کی عمر تریسٹھ سال کی تھی ۔", "b:3905": "جب سے میں نے ہوش سنبھالا میں نے اپنے ماں باپ کو دین اسلام ہی پر پایا اور کوئی دن ایسا نہیں گزرتا تھا جس میں رسول کریم صلی اللہ علیہ وسلم ہمارے گھر صبح و شام دونوں وقت تشریف نہ لاتے ہوں ، پھر جب ( مکہ میں ) مسلمانوں کو ستایا جانے لگا تو حضرت ابوبکر رضی اللہ عنہ حبشہ کی ہجرت کا ارادہ کر کے نکلے ۔ جب آپ مقام برک غماد پر پہنچے تو آپ کی ملاقات ابن الدغنہ سے ہوئی جو قبیلہ قارہ کا سردار تھا ۔ اس نے پوچھا ابوبکر ( رضی اللہ عنہ ) ! کہاں کا ارادہ ہے ؟ انہوں نے کہا کہ میری قوم نے مجھے نکال دیا ہے اب میں نے ارادہ کر لیا ہے کہ ملک ملک کی سیاحت کروں ( اور آزادی کے ساتھ ) اپنے رب کی عبادت کروں ۔ ابن الدغنہ نے کہا لیکن ابوبکر ! تم جیسے انسان کو اپنے وطن سے نہ خود نکلنا چاہئے اور نہ اسے نکالا جانا چاہیے ۔ تم محتاجوں کی مدد کرتے ہو ، صلہ رحمی کرتے ہو ۔ بے کسوں کا بوجھ اٹھاتے ہو ، مہمان نوازی کرتے ہو اور حق پر قائم رہنے کی وجہ سے کسی پر آنے والی مصیبتوں میں اس کی مدد کرتے ہو ، میں تمہیں پناہ دیتا ہوں واپس چلو اور اپنے شہر ہی میں اپنے رب کی عبادت کرو ۔ چنانچہ وہ واپس آ گئے اور ابن الدغنہ بھی آپ کے ساتھ واپس آیا ۔ اس کے بعد ابن الدغنہ قریش کے تمام سرداروں کے یہاں شام کے وقت گیا اور سب سے اس نے کہا کہ ابوبکر ( رضی اللہ عنہ ) جیسے شخص کو نہ خود نکلنا چاہیے اور نہ نکالا جانا چا ہیے کیا تم ایسے شخص کو نکال دو گے جو محتاجوں کی امداد کرتا ہے ، صلہ رحمی کرتا ہے ، بے کسوں کا بوجھ اٹھا تا ہے ، مہمان نوازی کرتا ہے اور حق کی وجہ سے کسی پر آنے والی مصیبتوں میں اس کی مدد کرتا ہے ؟ قریش نے ابن الدغنہ کی پناہ سے انکا ر نہیں کیا صرف اتنا کہا کہ ابوبکر رضی اللہ عنہ سے کہہ دو ، کہ اپنے رب کی عبادت اپنے گھر کے اندر ہی کیا کریں ، وہیں نماز پڑھیں اور جو جی چاہے وہیں پڑھیں ، اپنی عبادات سے ہمیں تکلیف نہ پہنچا ئیں ، اس کا اظہار نہ کریں کیونکہ ہمیں اس کا ڈر ہے کہ کہیں ہماری عورتیں اور بچے اس فتنہ میں نہ مبتلا ہو جائیں ۔ یہ باتیں ابن الدغنہ نے حضرت ابوبکر رضی اللہ عنہ سے بھی آ کر کہہ دیں کچھ دنوں تک تو آپ اس پر قائم رہے اور اپنے گھر کے اندر ہی اپنے رب کی عبادت کرتے رہے ، نہ نماز بر سر عام پڑھتے اور نہ گھر کے سوا کسی اورجگہ تلاوت قرآن کرتے تھے لیکن پھر انہوں نے کچھ سوچا اور اپنے گھر کے سامنے نماز پڑھنے کے لئے ایک جگہ بنائی جہاں آپ نے نماز پڑھنی شروع کی اور تلاوت قرآن بھی وہیں کرنے لگے ، نتیجہ یہ ہوا کہ وہاں مشرکین کی عورتوں اور بچوں کا مجمع ہونے لگا ۔ وہ سب حیرت اور پسندیدگی کے ساتھ دیکھتے رہا کرتے تھے ۔ حضرت ابوبکر رضی اللہ عنہ بڑے نرم دل انسان تھے ۔ جب قرآن مجید کی تلاوت کرتے تو آنسو ؤں کو روک نہ سکتے تھے ۔ اس صورت حال سے مشرکین قریش کے سردار گھبراگئے اور انہوں نے ابن الدغنہ کو بلا بھیجا ، جب ابن الدغنہ ان کے پاس آیا تو انہوں نے اس سے کہا کہ ہم نے ابوبکر کے لئے تمہاری پناہ اس شرط کے ساتھ تسلیم کی تھی کہ اپنے رب کی عبادت وہ اپنے گھر کے اندر کیا کریں لیکن انہوں نے شرط کی خلاف ورزی کی ہے اور اپنے گھر کے سامنے نماز پڑھنے کے لئے ایک جگہ بنا کر برسر عام نماز پڑھنے اور تلاوت قرآن کرنے لگے ہیں ۔ ہمیں اس کا ڈر ہے کہ کہیں ہماری عورتیں اور بچے اس فتنے میں نہ مبتلا ہو جائیں اس لئے تم انہیں روک دو ، اگر انہیں یہ شرط منظور ہو کہ اپنے رب کی عبادت صرف اپنے گھر کے اندر ہی کیا کریں تو وہ ایسا کر سکتے ہیں لیکن اگر وہ اظہار ہی کریں تو ان سے کہو کہ تمہاری پناہ واپس دے دیں ، کیونکہ ہمیں یہ پسند نہیں کہ تمہاری دی ہوئی پناہ میں ہم دخل اندازی کریں لیکن ابوبکر کے اس اظہار کو بھی ہم برداشت نہیں کر سکتے ۔ حضرت عائشہ رضی اللہ عنہا نے بیان کیا کہ پھر ابن الدغنہ ابوبکر رضی اللہ عنہ کے یہاں آیا اور اس نے کہا کہ جس شرط کے ساتھ میں نے آپ کے ساتھ عہد کیا تھا وہ آپ کو معلوم ہے ، اب یا آپ اس شرط پر قائم رہیے یا پھر میرے عہد کو واپس کیجئے کیونکہ یہ مجھے گوار ا نہیں کہ عرب کے کانوں تک یہ بات پہنچے کہ میں نے ایک شخص کو پناہ دی تھی ۔ لیکن اس میں ( قریش کی طرف سے ) دخل اندازی کی گئی ۔ اس پر حضرت ابوبکر رضی اللہ عنہ نے کہا میں تمہاری پناہ واپس کرتا ہوں اور اپنے رب عزوجل کی پناہ پر راضی اور خوش ہوں ۔ حضور صلی اللہ علیہ وسلم ان دنوں مکہ میں تشریف رکھتے تھے ۔ آپ نے مسلمانوں سے فرمایا کہ تمہاری ہجرت کی جگہ مجھے خواب میں دکھائی گئی ہے وہا ں کھجور کے باغات ہیں اور دو پتھریلے میدانوں کے درمیان واقع ہے ، چنانچہ جنہیں ہجرت کرنی تھی انہوں نے مدینہ کی طرف ہجرت کی اور جو لوگ سرزمین حبشہ ہجرت کر کے چلے گئے تھے وہ بھی مدینہ چلے آئے ، حضرت ابوبکر رضی اللہ عنہ نے بھی مدینہ ہجرت کی تیار ی شروع کر دی لیکن حضور صلی اللہ علیہ وسلم نے ان سے فرمایا کہ کچھ دنوں کے لئے توقف کرو ۔ مجھے توقع ہے کہ ہجرت کی اجازت مجھے بھی مل جائے گی ۔ ابوبکر رضی اللہ عنہ نے عرض کیا کیا واقعی آپ کو بھی اس کی توقع ہے ، میرے باپ آپ پر فدا ہوں ۔ حضور صلی اللہ علیہ وسلم نے فرمایا کہ ہاں ۔ حضرت ابوبکر رضی اللہ عنہ نے حضور صلی اللہ علیہ وسلم کی رفاقت سفر کے خیال سے اپنا ارادہ ملتوی کر دیا اور دو اونٹنیوں کو جو ان کے پاس تھیں کیکر کے پتے کھلا کر تیار کرنے لگے چار مہینے تک ۔ ابن شہاب نے بیان کیا ، ان سے عروہ نے کہ حضرت عائشہ رضی اللہ عنہا نے کہا ، ایک دن ہم ابوبکر رضی اللہ عنہ کے گھر بیٹھے ہوئے تھے بھری دوپہر تھی کہ کسی نے حضرت ابوبکر رضی اللہ عنہ سے کہا رسول اللہ صلی اللہ علیہ وسلم سر پر رومال ڈالے تشریف لا رہے ہیں ، حضور صلی اللہ علیہ وسلم کا معمول ہمارے یہاں اس وقت آنے کا نہیں تھا ۔ حضرت ابوبکر رضی اللہ عنہ بولے حضور صلی اللہ علیہ وسلم پر میرے ماں باپ فدا ہوں ۔ ایسے وقت میں آپ کسی خاص وجہ سے ہی تشریف لا رہے ہوں گے ، انہوں نے بیان کیا کہ پھر حضور صلی اللہ علیہ وسلم تشریف لائے اور اندر آنے کی اجازت چاہی ٰ ابوبکر رضی اللہ عنہ نے آپ کو اجازت دی تو آپ اندر داخل ہوئے پھر حضور صلی اللہ علیہ وسلم نے ان سے فرمایا اس وقت یہاں سے تھوڑی دیر کے لئے سب کو اٹھادو ۔ ابوبکر رضی اللہ عنہ نے عرض کیا یہاں اس وقت تو سب گھر کے ہی آدمی ہیں ، میرے باپ آپ پر فدا ہوں ، یا رسول اللہ ! حضور صلی اللہ علیہ وسلم نے اس کے بعد فرمایا کہ مجھے ہجرت کی اجازت دے دی گئی ہے ۔ ابوبکر رضی اللہ عنہ نے عرض کیا میرے ماں باپ آپ پر فدا ہوں یا رسول اللہ ! کیا مجھے رفاقت سفر کا شرف حاصل ہو سکے گا ؟ حضور صلی اللہ علیہ وسلم نے فرمایا کہ ہاں انہوں نے عرض کیا یا رسول اللہ ! میرے ماں باپ آپ پر فدا ہوں ان دونوں میں سے ایک اونٹنی آپ لے لیجئے ! حضور صلی اللہ علیہ وسلم نے فرمایا لیکن قیمت سے ، حضرت عائشہ رضی اللہ عنہا نے بیان کیا کہ پھر ہم نے جلدی جلدی ان کے لئے تیاریاں شروع کر دیں اور کچھ توشہ ایک تھیلے میں رکھ دیا ۔ اسماء بنت ابی بکر رضی اللہ عنہا نے اپنے پٹکے کے ٹکڑے کر کے تھیلے کا منہ اس سے باندھ دیا اور اسی وجہ سے انکانام ذات النطاقین ( دوپٹکے والی ) پڑ گیا عائشہ رضی اللہ عنہا نے بیان کیا کہ پھر رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ نے جبل ثور کے غار میں پڑاؤ کیا اور تین راتیں گزاریں عبداللہ بن ابی بکر رضی اللہ عنہما رات وہیں جا کر گزارا کرتے تھے ، یہ نو جوان بہت سمجھدار تھے اور ذہین بےحد تھے ۔ سحر کے وقت وہاں سے نکل آتے اور صبح سویرے ہی مکہ پہنچ جاتے جیسے وہیں رات گزری ہو ۔ پھر جو کچھ یہاں سنتے اور جس کے ذریعہ ان حضرات کے خلاف کاروائی کے لیے کوئی تدبیر کی جاتی تو اسے محفوظ رکھتے اور جب اندھیرا چھا جاتا تو تمام اطلاعات یہاں آ کر پہنچاتے ۔ ابوبکر رضی اللہ عنہ کے غلام عامر بن فہیرہ رضی اللہ عنہ آپ ہر دو کے لئے قریب ہی دودھ دینے والی بکری چرایا کرتے تھے اور جب کچھ رات گزر جاتی تو اسے غار میں لاتے تھے ۔ آپ اسی پر رات گزارتے اس دودھ کو گرم لوہے کے ذریعہ گرم کر لیا جاتا تھا ۔ صبح منہ اندھیرے ہی عامر بن فہیرہ رضی اللہ عنہ غار سے نکل آتے تھے ان تین راتوں میں روزانہ کا ان کا یہی دستور تھا ۔ حضرت ابوبکر رضی اللہ عنہ نے بنی الدیل جو بنی عبد بن عدی کی شاخ تھی ، کے ایک شخص کو راستہ بتانے کے لئے اجرت پر اپنے ساتھ رکھا تھا ۔ یہ شخص راستوں کا بڑا ماہر تھا ۔ آل عاص بن وائل سہمی کا یہ حلیف بھی تھا اور کفار قریش کے دین پر قائم تھا ۔ ان بزرگوں نے اس پر اعتماد کیا اور اپنے دونوں اونٹ اس کے حوالے کر دیئے ۔ قرار یہ پایا تھا کہ تین راتیں گزار کر یہ شخص غار ثور میں ان سے ملاقات کرے ۔ چنانچہ تیسری رات کی صبح کو وہ دونوں اونٹ لے کر ( آ گیا ) اب عامر بن فہیرہ رضی اللہ عنہ اور یہ راستہ بتانے والا ان حضرات کو ساتھ لے کر روانہ ہوئے ساحل کے راستے سے ہوتے ہوئے ۔", "b:3925": "سب سے پہلے ہمارے یہاں مصعب بن عمیر رضی اللہ عنہ اور ابن ام مکتوم رضی اللہ عنہ ( نابینا ) آئے یہ دونوں ( مدینہ کے ) مسلمانوں کو قرآن پڑھنا سکھاتے تھے ۔ اس کے بعد بلال ، سعداور عمار بن یاسر رضی اللہ عنہم آئے ۔ پھر عمربن خطاب رضی اللہ عنہ حضور صلی اللہ علیہ وسلم کے بیس صحابہ کو ساتھ لے کر آئے اور نبی کریم صلی اللہ علیہ وسلم ( حضرت ابوبکر رضی اللہ عنہ اور عامر بن فہیرہ کو ساتھ لے کر ) تشریف لائے ، مدینہ کے لوگوں کو جتنی خوشی اور مسرت حضور صلی اللہ علیہ وسلم کی تشریف آوری سے ہوئی میں نے کبھی انہیں کسی بات پر اس قدر خوش نہیں دیکھا ۔ لونڈیاں بھی ( خوشی میں ) کہنے لگیں کہ رسول اللہ صلی اللہ علیہ وسلم آ گئے حضور صلی اللہ علیہ وسلم جب تشریف لائے تو اس سے پہلے میں مفصل کی دوسری کئی سورتوں کے ساتھ سبح اسم ربک الاعلی بھی سیکھ چکا تھا ۔", "b:5013": "ایک صحابی ( خود ابو سعید خدری ) نے ایک دوسرے صحابی ( قتادہ بن نعمان رضی اللہ عنہ ) اپنے ماں جائے بھائی کو دیکھا کہ وہ رات کو سورۃ قل ھو اللہ باربار پڑھ رہے ہیں ۔ صبح ہوئی تو وہ صحابی ( ابوسعید رضی اللہ عنہ ) رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور آنحضرت سے اس کا ذکر کیا گویا انہوں نے سمجھا کہ اس میں کوئی بڑا ثواب نہ ہو گا ۔ آنحضرت نے فرمایا کہ اس ذات کی قسم جس کے ہاتھ میں میری جان ہے ! یہ سورت قرآن مجید کے ایک تہائی حصہ کے برابر ہے ۔", "b:5027": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تم میں سب سے بہتر وہ ہے جو قرآن مجید پڑھے اور پڑھائے ۔ سعد بن عبیدہ نے بیان کیا کہ ابوعبدالرحمن سلمی نے لوگوں کو عثمان رضی اللہ عنہ کے زمانہ خلافت سے حجاج بن یوسف کے عراق کے گورنر ہونے تک قرآن مجید کی تعلیم دی ۔ وہ کہا کرتے تھے کہ یہی حدیث ہے جس نے مجھے اس جگہ ( قرآن مجید پڑھا نے کے لئے ) بٹھا رکھا ہے ۔", "b:528": "آپ صلی اللہ علیہ وسلم فرماتے تھے کہ اگر کسی شخص کے دروازے پر نہر جاری ہو اور وہ روزانہ اس میں پانچ پانچ دفعہ نہائے تو تمہارا کیا گمان ہے ۔ کیا اس کے بدن پر کچھ بھی میل باقی رہ سکتا ہے ؟ صحابہ نے عرض کی کہ نہیں یا رسول اللہ ! ہرگز نہیں ۔ آپ صلی اللہ علیہ وسلم نے فرمایا کہ یہی حال پانچوں وقت کی نمازوں کا ہے کہ اللہ پاک ان کے ذریعہ سے گناہوں کو مٹا دیتا ہے ۔", "b:6018": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے پڑوسی کو تکلیف نہ پہنچائے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اپنے مہمان کی عزت کرے اور جو کوئی اللہ اور آخرت کے دن پر ایمان رکھتا ہو وہ اچھی بات زبان سے نکالے ورنہ خاموش رہے ۔", "b:6114": "رسول کریم صلی اللہ علیہ وسلم نے فرمایا پہلوان وہ نہیں ہے جو کشتی لڑنے میں غالب ہو جائے بلکہ اصلی پہلوان تو وہ ہے جو غصہ کی حالت میں اپنے آپ پر قابو پائے ۔ بے قابو نہ ہو جائے ۔", "b:604": "جب مسلمان ( ہجرت کر کے ) مدینہ پہنچے تو وقت مقرر کر کے نماز کے لیے آتے تھے ۔ اس کے لیے اذان نہیں دی جاتی تھی ۔ ایک دن اس بارے میں مشورہ ہوا ۔ کسی نے کہا نصاریٰ کی طرح ایک گھنٹہ لے لیا جائے اور کسی نے کہا کہ یہودیوں کی طرح نرسنگا ( بگل بنا لو ، اس کو پھونک دیا کرو ) لیکن حضرت عمر رضی اللہ عنہ نے فرمایا کہ کسی شخص کو کیوں نہ بھیج دیا جائے جو نماز کے لیے پکار دیا کرے ۔ اس پر آنحضرت صلی اللہ علیہ وسلم نے ( اسی رائے کو پسند فرمایا اور بلال سے ) فرمایا کہ بلال ! اٹھ اور نماز کے لیے اذان دے ۔", "b:678": "آپ نے فرمایا کہ نبی کریم صلی اللہ علیہ وسلم بیمار ہوئے اور جب بیماری شدت اختیار کر گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا کہ ابوبکر ( رضی اللہ عنہ ) سے کہو کہ وہ لوگوں کو نماز پڑھائیں ۔ اس پر حضرت عائشہ رضی اللہ عنہا بولیں کہ وہ نرم دل ہیں جب آپ کی جگہ کھڑے ہوں گے تو ان کے لئے نماز پڑھانا مشکل ہو گا ۔ آپ صلی اللہ علیہ وسلم نے پھر فرمایا کہ ابوبکر سے کہو کہ وہ نماز پڑھائیں ۔ حضرت عائشہ رضی اللہ عنہا نے پھر وہی بات کہی ۔ آپ صلی اللہ علیہ وسلم نے پھر فرمایا کہ ابوبکر سے کہو کہ نماز پڑھائیں ، تم لوگ صواحب یوسف ( زلیخا ) کی طرح ( باتیں بناتی ) ہو ۔ آخر ابوبکر صدیق رضی اللہ عنہ کے پاس آدمی بلانے آیا اور آپ نے لوگوں کو نبی کریم صلی اللہ علیہ وسلم کی زندگی میں ہی نماز پڑھائی ۔", "b:6306": "اور ان سے رسول اللہ صلی اللہ علیہ وسلم نے کہ سیدالاستغفار ۔ ( مغفرت مانگنے کے سب کلمات کا سردار ) یہ ہے یوں کہے ، ‏ اے اللہ ! تو میرا رب ہے ، تیرے سوا کوئی معبود نہیں ۔ تو نے ہی مجھے پیدا کیا اور میں تیرا ہی بندہ ہوں میں اپنی طاقت کے مطابق تجھ سے کئے ہوئے عہد اور وعدہ پرقائم ہوں ۔ ان بری حرکتوں کے عذاب سے جو میں نے کی ہیں تیری پناہ مانگتا ہوں مجھ پر نعمتیں تیری ہیں اس کااقرار کرتا ہوں ۔ میری مغفرت کر دے کہ تیرے سوا اور کوئی بھی گناہ نہیں معاف کرتا ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا کہ جس نے اس دعا کے الفاظ پر یقین رکھتے ہوئے دل سے ان کو کہہ لیا اور اسی دن اس کا انتقال ہو گیا شام ہونے سے پہلے تو وہ جنتی ہے اور جس نے اس دعا کے الفاظ پر یقین رکھتے ہوئے رات میں ان کو پڑھ لیا اور پھر اس کاصبح ہونے سے پہلے انتقال ہو گیا تو وہ جنتی ہے ۔", "b:6384": "ہم نبی کریم صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھے جب ہم کسی بلند جگہ پر چڑھتے تو تکبیر کہتے ۔ آنحضرت صلی اللہ علیہ وسلم نے فرمایا لوگو ! اپنے اوپر رحم کرو ، تم کسی بہرے غائب خدا کو نہیں پکارتے ہو تم تو اس ذات کو پکارتے ہو جو بہت زیادہ سننے والا ، بہت زیادہ دیکھنے والا ہے ۔ پھر آنحضرت صلی اللہ علیہ وسلم میرے پاس تشریف لائے ۔ میں اس وقت زیر لب کہہ رہا تھا ۔ ” لا حول ولا قوۃ إلا بالله “ آنحضرت صلی اللہ علیہ وسلم نے فرمایا ، عبداللہ بن قیس کہو ” لا حول ولا قوۃ إلا بالله “ کیونکہ یہ جنت کے خزانوں میں سے ایک خزانہ ہے ، یا آنحضرت صلی اللہ علیہ وسلم نے یہ فرمایا میں تمہیں ایک ایسا کلمہ نہ بتا دوں جو جنت کے خزانوں میں سے ایک خزانہ ہے ۔ لا حول ولا قوۃ إلا بالله ۔", "b:6389": "نبی کریم صلی اللہ علیہ وسلم کی اکثر یہ دعا ہوا کرتی تھی اللهم ربنا آتنا في الدنيا حسنۃ ، ‏‏‏‏ وفي الآخرۃ حسنۃ ، ‏‏‏‏ وقنا عذاب النار ” اے اللہ ! ہمیں دنیا میں بھلائی ( حسنہ ) عطا کر اور آخرت میں بھلائی عطاکر اور ہمیں دوزخ سے بچا ۔ “", "b:6405": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ، جس نےسبحان اللہ وبحمدہ دن میں سو مرتبہ کہا ، اس کے گناہ معاف کر دئیے جاتے ہیں ، خواہ سمندر کی جھاگ کے برابر ہی کیوں نہ ہوں ۔", "b:6682": "رسول اللہ صلی اللہ علیہ وسلم نے فرمایا دو کلمے جو زبان پر ہلکے ہیں لیکن ترازو پر ( آخرت میں ) بھاری ہیں اور اللہ رحمن کے یہاں پسندیدہ ہیں وہ یہ ہیں ۔ سبحان اللہ و بحمدہ سبحان اللہ العظیم ۔"};
